/* StewardMD - management/treatment briefs for the NON-INFECTIVE differentials
   shown by the Clinical Reasoning (DX) engine. Keyed by DX diagnosis id.
     dx: how to confirm | tx: first-line management steps | ix: key investigations
     dispo: disposition | src: source(s)
   Concise decision-support aligned to Harrison Principles of Internal Medicine
   22e (2025) + cited society guidelines, and CROSS-CHECKED against the Harrison
   22e text (entries marked "rev. Harrison 22e <page>" were refined in that pass).
   NOT a substitute for clinical judgement / local protocol / full prescribing
   references - verify doses (renal/hepatic/pregnancy, interactions) before use. */
(function () {
  window.DX_MGMT = {
    // ── High-risk toxicology canonical objects (gold122) — added so general
    //    "how to treat X" knowledge queries retrieve management. Standard,
    //    guideline-aligned content; not individualized advice. ──
    paracetamol_poisoning: { name: "Paracetamol (acetaminophen) poisoning", class: "non_infective", system: "Toxicology",
      syn: ["acetaminophen overdose", "paracetamol overdose", "APAP toxicity", "acetaminophen poisoning"],
      dx: "Often asymptomatic early; nausea/RUQ discomfort then hepatotoxicity at 24–72 h. Plot a level drawn ≥4 h post-ingestion on the Rumack–Matthew nomogram; treat staggered/unknown-timing ingestions empirically.",
      tx: ["Resuscitate; activated charcoal only if presenting within ~1–2 h and airway is protected.",
        "N-ACETYLCYSTEINE (NAC) is the antidote — start if the 4-hour level is above the treatment line, or empirically for staggered / unknown-timing / late (>8 h) presentation without waiting for the level.",
        "Continue NAC and monitor for acute liver failure (rising INR, encephalopathy, acidosis, hypoglycaemia).",
        "Refer early to a liver/transplant unit using King's College criteria; correct hypoglycaemia and coagulopathy.",
        "Contact a poisons service for staggered/massive ingestion or established hepatotoxicity."],
      ix: ["Paracetamol level at ≥4 h post-ingestion", "LFTs, INR, creatinine, glucose", "ABG/lactate if severe"],
      dispo: "Admit; ALF → transplant centre/ICU.", src: "Harrison 22e · toxicology guidelines" },
    methanol_poisoning: { name: "Methanol poisoning", class: "non_infective", system: "Toxicology",
      syn: ["methanol toxicity", "methyl alcohol poisoning", "toxic alcohol methanol"],
      dx: "Latent period then visual disturbance/blindness with a high-anion-gap metabolic acidosis and a raised osmolar gap after ingestion of adulterated spirits/solvents.",
      tx: ["Resuscitate; IV sodium bicarbonate for severe metabolic acidosis.",
        "FOMEPIZOLE (preferred) — or ethanol if unavailable — to inhibit alcohol dehydrogenase and block formation of the toxic metabolite (formic acid).",
        "Folinic/folic acid to accelerate formate metabolism.",
        "HAEMODIALYSIS for severe acidosis, visual symptoms, high methanol levels, or renal failure.",
        "Contact a poisons service; monitor acid–base, osmolar/anion gap and vision."],
      ix: ["Serum methanol ± ethanol level", "ABG, anion gap and osmolar gap", "U&E, lactate; fundoscopy"],
      dispo: "ICU; dialysis for severe toxicity.", src: "Harrison 22e · toxicology guidelines" },
    snakebite_envenomation: { name: "Snakebite envenomation", class: "non_infective", system: "Toxicology",
      syn: ["snake bite", "venomous snakebite", "snake envenomation"],
      dx: "Fang marks with local swelling; systemic envenomation shows coagulopathy/bleeding, neurotoxicity (ptosis, bulbar/respiratory weakness) or AKI. Use the 20-minute whole-blood clotting test for coagulopathy.",
      tx: ["Reassure; immobilise the limb at heart level and transport urgently. Do NOT apply a tourniquet, incise, or suck the wound.",
        "ANTIVENOM (polyvalent ASV) for any sign of systemic envenomation — coagulopathy on 20-min WBCT, neurotoxicity, or marked local spread — titrated to reversal; be ready to treat ASV anaphylaxis.",
        "Neurotoxic (elapid) bites: neostigmine + atropine trial and ventilatory support as needed.",
        "Supportive care for AKI (dialysis if required); tetanus prophylaxis; analgesia (avoid NSAIDs if coagulopathic).",
        "Serial monitoring of clotting, neurology and renal function; repeat ASV if coagulopathy persists."],
      ix: ["20-minute whole-blood clotting test", "Coagulation profile, platelets, creatinine, CK, urinalysis", "Monitor neurology and respiration"],
      dispo: "Admit/observe; ICU for neurotoxicity or shock.", src: "Harrison 22e · WHO/national snakebite guidelines" },
    STATUS_EPILEPTICUS: { name: "Status epilepticus", class: "non_infective", system: "Neurology",
      syn: ["convulsive status epilepticus", "refractory status epilepticus"],
      dx: "A seizure lasting >5 min or recurrent seizures without recovery of consciousness — a time-critical emergency.",
      tx: ["ABC; give oxygen, secure IV access, check glucose (treat hypoglycaemia) and give thiamine if malnourished/alcohol.",
        "First-line: IV benzodiazepine — lorazepam (or IM midazolam if no IV) — repeat once if seizures continue.",
        "Second-line if ongoing: IV antiseizure load — levetiracetam, sodium valproate, or (fos)phenytoin.",
        "Refractory status: intubate and start an anaesthetic infusion (midazolam or propofol) with continuous EEG.",
        "Identify and treat the cause (hypoglycaemia, infection/meningitis, electrolytes, eclampsia, toxins, AED non-adherence)."],
      ix: ["Glucose, electrolytes, calcium, magnesium", "AED levels, toxicology screen", "EEG (esp. for non-convulsive); CT/MRI ± LP as indicated"],
      dispo: "ICU for refractory/ongoing seizures.", src: "Harrison 22e · NCS status epilepticus guideline" },
    migraine: { dx: "Recurrent moderate–severe, often unilateral throbbing headache ± aura, photophobia, nausea with a normal exam (ICHD-3). Image only for red flags.", tx: ["Acute: NSAID (e.g. naproxen) or paracetamol; add an oral triptan (e.g. sumatriptan 50–100 mg) if no vascular contraindication.","Add an antiemetic (metoclopramide / prochlorperazine) for nausea.","Treat early; rest in a dark, quiet room.","Limit acute drugs to <10–15 days/month to avoid medication-overuse headache.","Prophylaxis if frequent/disabling: propranolol, amitriptyline, topiramate or candesartan."], ix: ["Clinical (ICHD-3)","Neuroimaging only if red flags"], dispo: "Outpatient; neurology referral if refractory or atypical.", src: "Harrison 22e · ICHD-3" },
    tension_ha: { dx: "Bilateral, pressing/tightening, mild–moderate headache without migrainous features or red flags.", tx: ["Simple analgesia: paracetamol or an NSAID, used sparingly.","Address triggers — stress, poor sleep, posture, caffeine, eye strain.","Prophylaxis with low-dose amitriptyline if chronic (>15 days/month).","Avoid opioids and frequent analgesia (medication-overuse risk)."], ix: ["Clinical diagnosis"], dispo: "Outpatient.", src: "Harrison 22e" },
    sah: { dx: "Sudden thunderclap (worst-ever) headache ± neck stiffness, photophobia, transient LOC. Non-contrast CT head; LP for xanthochromia if CT negative and high suspicion.", tx: ["EMERGENCY — resuscitate (ABC), neurosurgery / stroke team immediately.","CT angiography to localise aneurysm; secure aneurysm early (endovascular coiling or clipping).","Nimodipine 60 mg PO q4h to reduce vasospasm-related deficits.","Control pain and BP (avoid extreme swings); bed rest, analgesia, antiemetics.","Monitor for hydrocephalus, rebleeding, vasospasm, hyponatraemia."], ix: ["Non-contrast CT","LP (xanthochromia)","CT/DSA angiography"], dispo: "ICU + neurosurgery, urgent.", src: "Harrison 22e · AHA/ASA SAH" },
    ischemic_stroke: { dx: "Sudden focal neurological deficit; non-contrast CT to exclude haemorrhage, then confirm ischaemia. Establish last-known-well time.", tx: ["TIME-CRITICAL — activate stroke pathway, non-contrast CT immediately.","IV thrombolysis (alteplase/tenecteplase) if within window and no contraindication.","Mechanical thrombectomy for large-vessel occlusion up to 24 h in selected patients.","Aspirin 300 mg once haemorrhage excluded (delay 24 h after thrombolysis).","Admit to stroke unit; permissive hypertension, glucose/temperature control, swallow screen, early secondary prevention."], ix: ["Non-contrast CT ± CT angio/perfusion","Glucose, ECG","Carotid imaging, echo"], dispo: "Stroke unit / ICU.", src: "Harrison 22e · AHA/ASA stroke" },
    ich: { dx: "Sudden focal deficit ± reduced consciousness, headache, vomiting; non-contrast CT shows intraparenchymal haemorrhage.", tx: ["Resuscitate; protect airway if GCS ≤8.","Reverse anticoagulation urgently (vitamin K + PCC for warfarin; specific reversal agents for DOACs).","Lower SBP to ~140 mmHg (e.g. IV labetalol/nicardipine).","Manage raised ICP; neurosurgical referral (esp. cerebellar bleed, hydrocephalus).","Admit to stroke unit/ICU; VTE prophylaxis (mechanical first)."], ix: ["Non-contrast CT","Coagulation profile","CT angio if structural cause suspected"], dispo: "ICU / neurosurgery.", src: "Harrison 22e · AHA/ASA ICH" },
    brain_tumour: { dx: "Progressive headache (worse on waking/Valsalva), focal signs, new seizures, or papilloedema. MRI brain with contrast.", tx: ["MRI with contrast; refer neuro-oncology / neurosurgery.","Dexamethasone for symptomatic vasogenic oedema (with PPI cover).","Antiepileptics only if seizures have occurred (not routine prophylaxis).","Definitive therapy (surgery, radiotherapy, chemotherapy) is tumour-specific via MDT."], ix: ["MRI brain + contrast","Staging imaging if metastasis suspected","Histology"], dispo: "Refer neuro-oncology/neurosurgery.", src: "Harrison 22e" },
    iih: { dx: "Headache + visual disturbance with papilloedema, typically a young obese woman; normal imaging; LP opening pressure raised with normal CSF.", tx: ["MRI + MR venography (exclude mass/venous sinus thrombosis), then LP to confirm raised opening pressure with normal CSF.","Weight loss is central; consider a GLP-1 receptor agonist if unable to lose weight by diet.","Acetazolamide first-line (250-500 mg bid) to lower CSF production; topiramate is the next agent if ineffective.","Formal perimetry and urgent ophthalmology if visual loss; severe/progressive loss needs CSF diversion (lumboperitoneal shunt) or optic-nerve-sheath fenestration.","Stop precipitants (tetracyclines, vitamin A, retinoids)."], ix: ["Fundoscopy/formal perimetry","MRI + MRV","LP with opening pressure"], dispo: "Refer neurology + ophthalmology.", src: "Harrison 22e · rev. Harrison 22e 116-117," },
    temporal_arteritis: { dx: "New headache, scalp tenderness, jaw claudication ± visual symptoms in age >50; raised ESR/CRP; temporal artery biopsy or US confirms.", tx: ["START high-dose oral glucocorticoids IMMEDIATELY on suspicion - do not wait for biopsy (sight-threatening); IV methylprednisolone if visual loss.","Prednisone ~40-80 mg/day (Harrison cites 80 mg daily for the first 4-6 weeks).","Arrange temporal artery biopsy (or Doppler US) as soon as practical - steroids do not abolish findings immediately but can mask them with prolonged treatment.","Gastroprotection, bone protection, glucose monitoring; tocilizumab as a steroid-sparing alternative.","Slow steroid taper guided by symptoms and ESR/CRP."], ix: ["ESR, CRP","Temporal artery biopsy / Doppler US"], dispo: "Urgent rheumatology ± ophthalmology.", src: "Harrison 22e · ACR/EULAR GCA · rev. Harrison 22e 115," },
    acs: { dx: "Ischaemic chest pain ± ECG changes and troponin rise. Distinguish STEMI from NSTE-ACS by ECG.", tx: ["Aspirin 300 mg + a second antiplatelet (ticagrelor/clopidogrel); analgesia, oxygen only if hypoxic.","STEMI: primary PCI (or thrombolysis if PCI unavailable) — time-critical.","NSTE-ACS: anticoagulate (e.g. fondaparinux/LMWH) and risk-stratify (GRACE) for early angiography.","Start high-intensity statin, beta-blocker and ACE-inhibitor as tolerated.","Continuous monitoring; treat arrhythmia/heart failure."], ix: ["Serial ECG + troponin","Echo","Coronary angiography"], dispo: "CCU / cath lab.", src: "Harrison 22e · ESC ACS" },
    aortic_dissection: { dx: "Sudden tearing chest/back pain ± pulse/BP differential, new aortic regurgitation, widened mediastinum. CT angiography aorta.", tx: ["EMERGENCY — CT angiogram of the aorta; involve cardiothoracic surgery.","Control HR then BP: IV beta-blocker (labetalol/esmolol) to HR <60 and SBP ~100–120, add vasodilator.","Type A (ascending): emergency surgery. Type B: usually medical ± endovascular for complications.","Adequate analgesia (reduces sympathetic drive).","Cross-match blood; ICU monitoring."], ix: ["CT angiography (or TOE)","ECG, troponin (exclude MI mimic)","Group & save"], dispo: "ICU + cardiothoracic surgery.", src: "Harrison 22e · ESC aortic" },
    pe: { dx: "Pleuritic pain/dyspnoea/tachycardia ± leg DVT; risk-stratify (Wells), D-dimer if low probability, CTPA to confirm.", tx: ["Start anticoagulation on clinical suspicion if high probability (LMWH/DOAC).","Massive PE (shock): thrombolysis (or embolectomy) and resuscitation.","Confirm with CTPA (or V/Q); echo for RV strain in unstable patients.","Continue DOAC/LMWH→oral; duration ≥3 months (longer if unprovoked/recurrent).","Oxygen, analgesia; assess for cancer/thrombophilia if unprovoked."], ix: ["CTPA / V-Q","D-dimer (low prob)","ECG, troponin, echo (severity)"], dispo: "Admit; ICU if haemodynamically unstable.", src: "Harrison 22e · ESC PE" },
    pericarditis: { dx: "Sharp pleuritic chest pain relieved by sitting forward, friction rub, widespread saddle ST-elevation/PR depression. Exclude ACS and effusion/tamponade.", tx: ["NSAID (e.g. ibuprofen) + COLCHICINE for ~3 months (reduces recurrence).","Add gastroprotection; restrict strenuous activity until resolved.","Echo to assess for effusion/tamponade.","Treat the underlying cause; reserve steroids for specific indications (refractory, autoimmune).","Investigate for tamponade if hypotensive/raised JVP."], ix: ["ECG, echo","Troponin, CRP","Identify cause (viral, autoimmune, uraemic)"], dispo: "Outpatient if low-risk; admit if effusion/high-risk.", src: "Harrison 22e · ESC pericardial" },
    gerd_chest: { dx: "Burning retrosternal pain, postprandial/positional, acid regurgitation — once cardiac causes are excluded.", tx: ["EXCLUDE cardiac cause first if any doubt.","Lifestyle: weight loss, smaller meals, avoid late meals/triggers, elevate head of bed.","PPI trial (e.g. omeprazole) for 4–8 weeks.","Endoscopy if alarm features (dysphagia, weight loss, anaemia, age/onset).","Step down to lowest effective therapy."], ix: ["Clinical/PPI trial","OGD if alarm features"], dispo: "Outpatient.", src: "Harrison 22e · ACG GERD" },
    pneumothorax: { dx: "Sudden pleuritic pain and dyspnoea with reduced breath sounds; CXR confirms. Tension = hypotension + tracheal shift (clinical, treat immediately).", tx: ["TENSION pneumothorax: immediate needle decompression then chest drain — do NOT wait for imaging.","Primary, small, minimal symptoms: observation ± oxygen.","Larger/symptomatic: needle aspiration or chest drain.","Secondary (underlying lung disease): low threshold for chest drain + admission.","Smoking cessation; refer for recurrence (pleurodesis)."], ix: ["CXR (erect)","CT if complex","ABG if hypoxic"], dispo: "Admit if drained/secondary; ED observation if small primary.", src: "Harrison 22e · BTS pleural" },
    heart_failure: { dx: "Dyspnoea, orthopnoea, raised JVP, basal crackles, oedema; raised BNP/NT-proBNP; echo for ejection fraction.", tx: ["Acute pulmonary oedema: sit up, high-flow O2, IV loop diuretic (furosemide), IV nitrate if hypertensive.","Consider CPAP/NIV for severe respiratory distress.","Identify/treat precipitant (ischaemia, arrhythmia, non-adherence, infection).","Daily weights, fluid/salt restriction, monitor renal function and potassium.","Chronic HFrEF: ACEi/ARNI + beta-blocker + MRA + SGLT2 inhibitor."], ix: ["BNP/NT-proBNP","Echo","ECG, CXR, U&E, troponin"], dispo: "Admit; ICU/HDU if cardiogenic shock or NIV.", src: "Harrison 22e · ESC HF" },
    copd_exac_ni: { dx: "Increased dyspnoea/sputum/wheeze in known COPD without convincing infection. Assess for CO2 retention.", tx: ["Controlled oxygen targeting SpO2 88–92% (avoid over-oxygenation).","Nebulised salbutamol + ipratropium.","Oral prednisolone 30 mg for ~5 days.","Antibiotics only if increased purulent sputum / consolidation / ventilatory support.","NIV for persistent respiratory acidosis (pH <7.35 with hypercapnia)."], ix: ["ABG","CXR","ECG"], dispo: "Admit if hypoxic/acidotic; ICU/NIV if failing.", src: "Harrison 22e · GOLD" },
    cardiogenic_shock: { dx: "Hypotension with hypoperfusion despite adequate filling, due to pump failure (often after large MI). Raised lactate, low cardiac output, congestion.", tx: ["ICU; treat the cause — urgent revascularisation for ischaemic cause.","Inotrope/vasopressor (e.g. noradrenaline ± dobutamine) titrated to perfusion.","Cautious diuresis/fluid guided by filling status; treat arrhythmia.","Consider mechanical support (IABP/Impella/ECMO) in selected cases.","Invasive monitoring; serial lactate, urine output."], ix: ["Echo, ECG, troponin","Lactate, ABG","Coronary angiography"], dispo: "ICU / cardiology.", src: "Harrison 22e · ESC" },
    hypovolemic_shock: { dx: "Hypotension, tachycardia, cool peripheries, low JVP with a source of fluid/blood loss.", tx: ["Two large-bore IV lines; rapid balanced crystalloid resuscitation.","Haemorrhagic: activate major haemorrhage protocol — transfuse blood/products, tranexamic acid early.","Identify and control the source (surgery, endoscopy, IR, compression).","Titrate to perfusion (MAP, urine output, lactate clearance) — avoid over-resuscitation in active bleeding.","Keep warm; correct coagulopathy and calcium."], ix: ["FBC, cross-match, coagulation, lactate","Source imaging (CT/endoscopy)"], dispo: "Resuscitation area → ICU/theatre.", src: "Harrison 22e · ATLS" },
    anaphylaxis: { dx: "Acute onset of airway/breathing/circulation compromise ± urticaria/angioedema after an allergen exposure.", tx: ["IM ADRENALINE 0.5 mg (0.5 mL 1:1000) into anterolateral thigh — repeat every 5 min as needed. FIRST and most important step.","Remove trigger; lie flat with legs raised (sit up if breathing difficulty); high-flow oxygen.","IV fluid bolus for hypotension; nebulised salbutamol for bronchospasm.","Refractory: IV adrenaline infusion in a monitored setting.","Observe 6–12 h (biphasic risk); prescribe adrenaline auto-injector + allergy referral."], ix: ["Clinical diagnosis","Serial mast-cell tryptase","Allergy referral"], dispo: "Admit/observe; refractory → ICU.", src: "Harrison 22e · WAO/Resus Council" },
    adrenal_crisis: { dx: "Hypotension/shock, vomiting, hypoglycaemia, hyponatraemia ± known adrenal insufficiency or steroid withdrawal/stress. Treat on suspicion.", tx: ["Give IV HYDROCORTISONE 100 mg immediately — do NOT wait for cortisol results.","Aggressive IV fluids (0.9% saline) to correct volume and hypotension.","Correct hypoglycaemia (IV glucose) and electrolytes.","Treat the precipitant (often infection); continue hydrocortisone (e.g. 50 mg q6h) then taper.","Sick-day rules and steroid-emergency card education on recovery."], ix: ["Paired cortisol/ACTH (don't delay treatment)","U&E, glucose","Septic screen"], dispo: "Admit; ICU if shocked.", src: "Harrison 22e · Endocrine Society" },
    dka: { dx: "Hyperglycaemia + ketonaemia/ketonuria + high-anion-gap metabolic acidosis. Often a precipitant (infection, missed insulin, new T1DM).", tx: ["IV 0.9% saline resuscitation first (fluid deficit is large); careful in young/cardiac/renal.","Fixed-rate IV insulin infusion (~0.1 U/kg/h); continue basal insulin if on it.","Replace potassium once K <5.5 and urine output adequate (insulin drives K intracellularly).","Add dextrose when glucose <14 mmol/L; monitor ketones, glucose, K, pH hourly.","Find and treat the precipitant; do not stop insulin infusion until ketones cleared and eating."], ix: ["Glucose, ketones, VBG","U&E (potassium), bicarbonate","Septic screen, ECG"], dispo: "Admit (HDU/ICU if severe).", src: "Harrison 22e · ADA/JBDS DKA" },
    hypoglycemia: { dx: "Whipple's triad: low plasma glucose with autonomic/neuroglycopenic symptoms relieved by glucose. Identify cause (insulin/sulfonylurea, sepsis, etc.).", tx: ["Conscious: 15–20 g fast-acting oral carbohydrate, repeat in 15 min if still low.","Impaired/NBM: IV glucose (e.g. 100 mL 20%) or IM glucagon if no IV access.","Follow with longer-acting carbohydrate once recovered.","Sulfonylurea/long-acting insulin overdose: prolonged monitoring ± octreotide; admit.","Review drugs/diabetes regimen; address recurrent causes."], ix: ["Capillary + lab glucose","Insulin/C-peptide if cause unclear","Drug review"], dispo: "Observe; admit if drug-induced (long-acting).", src: "Harrison 22e · Endocrine Society" },
    metabolic_enceph: { dx: "Diffuse alteration of consciousness without focal deficit; asterixis, myoclonus. Identify the metabolic cause.", tx: ["Find and correct the cause — glucose, Na, Ca, uraemia, hypercapnia, ammonia, drugs, hypoxia, sepsis.","Support airway, oxygenation and circulation.","Empirical thiamine in at-risk patients; naloxone if opioid suspected.","Treat the underlying organ failure; review/stop offending drugs.","Monitor neurological status."], ix: ["Glucose, U&E, Ca, LFTs, ammonia, ABG","Toxicology","CT/EEG if cause unclear"], dispo: "Admit; ICU if airway risk.", src: "Harrison 22e" },
    hepatic_enceph: { dx: "Confusion/asterixis with chronic liver disease or porto-systemic shunt; a precipitant (GI bleed, infection, constipation, electrolytes, sedatives) is usually present.", tx: ["Identify and treat the PRECIPITANT (GI bleed, sepsis/SBP, constipation, hypokalaemia, dehydration, sedatives).","Lactulose titrated to 2–3 soft stools/day (oral or enema).","Add rifaximin for inadequate response / secondary prevention.","Avoid sedatives; do not over-restrict protein; correct electrolytes.","Manage underlying cirrhosis; assess for transplant."], ix: ["Ammonia (support, not diagnostic)","Septic screen incl. ascitic tap","Electrolytes, glucose"], dispo: "Admit; ICU if airway risk.", src: "Harrison 22e · AASLD/EASL" },
    drug_intox: { dx: "Altered consciousness/toxidrome after suspected ingestion; identify the agent and toxidrome; assess ABCs and risk.", tx: ["Resuscitate (airway, breathing, circulation); treat hypoglycaemia and give thiamine where relevant.","Identify the toxidrome; contact a poisons service (e.g. TOXBASE/Poison Centre) for agent-specific advice.","Decontamination (activated charcoal) only if early, airway-safe and appropriate agent.","Specific antidotes where indicated (naloxone, NAC, flumazenil caution, etc.); supportive monitoring.","Enhanced elimination/dialysis for selected toxins; psychiatric assessment after medical stabilisation."], ix: ["Glucose, paracetamol/salicylate levels","ABG, U&E, ECG, osmolar gap","Agent-specific levels"], dispo: "Admit/observe; ICU if severe.", src: "Harrison 22e · Poisons service" },
    dvt: { dx: "Unilateral leg pain/swelling/tenderness; risk-stratify (Wells), D-dimer if low probability, compression US confirms.", tx: ["Confirm proximal DVT with compression venous ultrasonography (D-dimer to help exclude when pretest probability is low).","Anticoagulate once confirmed: DOAC monotherapy (rivaroxaban or apixaban) first-line, or parenteral heparin/LMWH bridged to warfarin (target INR 2-3); warfarin not DOACs for antiphospholipid syndrome.","Treat at least 3 months; for first VTE consider extended/indefinite anticoagulation when there is no identifiable risk factor or a persistent risk factor (Harrison de-emphasises 'provoked vs unprovoked').","For cancer-associated VTE use LMWH or a DOAC (apixaban/edoxaban; avoid DOAC with GI cancer) and continue until cancer-free.","Compression stockings for symptomatic relief; check renal function for dosing; counsel on PE warning signs."], ix: ["Compression US","D-dimer (low prob)","FBC, renal function for dosing"], dispo: "Usually outpatient pathway.", src: "Harrison 22e · ASH/NICE VTE · rev. Harrison 22e 2204-2207" },
    asthma_exac: { dx: "Acute wheeze/dyspnoea/cough with reduced PEF; grade severity (PEF, SpO2, ability to speak, silent chest).", tx: ["High-flow oxygen to SpO2 94–98%; back-to-back nebulised salbutamol (+ ipratropium if severe).","Oral prednisolone 40–50 mg (or IV hydrocortisone) early.","IV magnesium sulfate for severe/life-threatening attacks.","Reassess with PEF/ABG; escalate to ICU for exhaustion, rising CO2 or silent chest.","Identify trigger; review inhaler technique/adherence and step-up preventer at discharge."], ix: ["PEF, SpO2","ABG if severe","CXR if atypical / no response"], dispo: "Admit if not responding; ICU if life-threatening.", src: "Harrison 22e · GINA/BTS" },
    atrial_fib: { dx: "Irregularly irregular pulse; ECG shows AF/flutter. Assess haemodynamic stability and onset/duration.", tx: ["Unstable (shock, ischaemia, pulmonary oedema): emergency synchronised DC cardioversion.","Stable: rate control with a beta-blocker or diltiazem/verapamil (digoxin if HF/hypotension).","Rhythm control (drug/electrical cardioversion) for selected/recent-onset; anticoagulate appropriately around cardioversion.","Anticoagulate per CHA2DS2-VASc (DOAC preferred) for stroke prevention.","Identify/treat triggers — sepsis, thyroid, electrolytes, alcohol, ischaemia."], ix: ["ECG","TFTs, electrolytes, echo","CHA2DS2-VASc / HAS-BLED"], dispo: "Admit if unstable/new with HF; else outpatient pathway.", src: "Harrison 22e · ESC AF" },
    aortic_stenosis: { dx: "Exertional syncope/angina/dyspnoea with an ejection-systolic murmur radiating to carotids, slow-rising pulse. Echo confirms severity.", tx: ["Echocardiography to grade severity; refer cardiology.","Avoid aggressive vasodilators/nitrates in severe AS (preload-dependent — risk of collapse).","Symptomatic severe AS → aortic valve replacement (surgical or TAVI).","Treat heart failure cautiously; manage concomitant CAD.","Endocarditis awareness/dental hygiene."], ix: ["Echocardiography","ECG, CXR","Coronary assessment pre-intervention"], dispo: "Cardiology referral; admit if decompensated.", src: "Harrison 22e · ESC/AHA valve" },
    pancreatitis: { dx: "Severe epigastric pain radiating to back with lipase/amylase >3× upper limit (or imaging). Identify cause (gallstones, alcohol); score severity.", tx: ["Aggressive early IV fluid resuscitation (balanced crystalloid) with monitoring.","Analgesia (opioids), antiemetics; early enteral nutrition as tolerated (avoid prolonged NBM).","NO routine antibiotics (only for proven infected necrosis/cholangitis).","Gallstone cause with cholangitis/obstruction: urgent ERCP; cholecystectomy on the same admission for mild biliary pancreatitis.","Severe/organ failure → HDU/ICU; monitor for necrosis, pseudocyst, collections."], ix: ["Lipase/amylase, LFTs, calcium, triglycerides","USS (gallstones)","CT if severe/uncertain"], dispo: "Admit; severe → HDU/ICU.", src: "Harrison 22e · ACG/IAP pancreatitis" },
    peptic_ulcer: { dx: "Epigastric pain ± upper-GI bleed (melaena/haematemesis). Risk-stratify bleed (Glasgow-Blatchford); OGD diagnostic and therapeutic.", tx: ["Active bleed: resuscitate (IV access, fluids/blood, transfuse to Hb ~70 g/L threshold); correct coagulopathy.","Urgent endoscopy (within 24 h) for haemostasis; IV PPI infusion for high-risk stigmata.","Test and treat H. pylori; stop NSAIDs; continue PPI.","Repeat endoscopy/IR embolisation or surgery for rebleeding.","Risk score (Glasgow-Blatchford/Rockall) guides admission and timing."], ix: ["FBC, U&E, coagulation, group&save","OGD","H. pylori testing"], dispo: "Admit; ICU/HDU if unstable bleed.", src: "Harrison 22e · NICE/ACG UGIB" },
    bowel_obstruction: { dx: "Colicky abdominal pain, vomiting, distension, absolute constipation; imaging (AXR/CT) confirms level and cause.", tx: ["'Drip and suck': NBM, IV fluids + electrolyte correction, nasogastric decompression.","CT to identify cause/level and detect ischaemia/strangulation.","Strangulation, closed-loop, ischaemia or perforation → urgent surgery.","Adhesional small-bowel obstruction without ischaemia: trial of conservative management.","Analgesia, antiemetics, urinary catheter; surgical review for all."], ix: ["AXR / CT abdomen","U&E, lactate, FBC","VBG"], dispo: "Surgical admission; theatre if strangulation.", src: "Harrison 22e · ACS/WSES" },
    mesenteric_ischemia: { dx: "Severe abdominal pain OUT OF PROPORTION to exam, ± AF/vascular disease, rising lactate. CT angiography is key.", tx: ["EMERGENCY — urgent CT angiography; do not delay for equivocal exam.","Resuscitate (fluids), broad-spectrum antibiotics, correct acidosis; NG decompression.","Urgent surgical/IR intervention — revascularisation (embolectomy/stent) and resect non-viable bowel.","Therapeutic anticoagulation for embolic/thrombotic arterial or venous occlusion.","ICU; high mortality — speed is critical."], ix: ["CT angiography","Lactate, ABG, FBC","ECG (AF)"], dispo: "Emergency surgery + ICU.", src: "Harrison 22e · WSES" },
    biliary_colic: { dx: "Postprandial RUQ/epigastric pain ± radiation to scapula, lasting <6 h, with gallstones on US and no fever/inflammation.", tx: ["Analgesia (NSAID/opioid) and antiemetics for the acute episode.","USS to confirm gallstones; check LFTs (exclude CBD stone/cholecystitis).","Low-fat dietary advice while awaiting surgery.","Elective laparoscopic cholecystectomy for symptomatic gallstones.","Escalate if fever, persistent pain or jaundice (cholecystitis/cholangitis)."], ix: ["USS abdomen","LFTs","MRCP if CBD stone suspected"], dispo: "Outpatient; surgical referral.", src: "Harrison 22e · NICE gallstones" },
    renal_colic: { dx: "Sudden severe loin-to-groin colicky pain ± haematuria, restless patient; non-contrast CT KUB confirms a stone and its size/site.", tx: ["Analgesia: an NSAID (e.g. IM/PR diclofenac) is first-line; opioid if NSAID contraindicated.","Antiemetic and fluids as needed; non-contrast CT KUB to confirm and size the stone.","Most stones <5 mm pass spontaneously — manage conservatively with analgesia ± medical expulsive therapy (alpha-blocker) and strain urine.","URGENT urology if obstruction WITH infection (obstructed infected system = emergency decompression), AKI, single kidney, or uncontrolled pain.","Larger/non-passing stones → urology for lithotripsy/ureteroscopy; advise hydration and prevention."], ix: ["Non-contrast CT KUB","Urinalysis, U&E, FBC/CRP","Stone analysis/metabolic work-up if recurrent"], dispo: "Often outpatient; admit if infected/obstructed, AKI, or intractable pain.", src: "Harrison 22e · EAU urolithiasis" },
    aaa: { dx: "Sudden abdominal/back/flank pain with hypotension and a pulsatile mass in an older patient — ruptured AAA until proven otherwise.", tx: ["EMERGENCY — call vascular surgery immediately; do NOT delay for extensive imaging if unstable.","Permissive hypotension (avoid aggressive fluids/overshoot before repair); large-bore access, major haemorrhage protocol.","Immediate transfer to theatre / endovascular suite for repair (EVAR or open).","CT angiography only if stable enough.","Cross-match; ICU post-op."], ix: ["Bedside US / CT angio if stable","Cross-match","FBC, coagulation"], dispo: "Emergency vascular surgery.", src: "Harrison 22e · ESVS" },
    thyroid_storm: { dx: "Severe thyrotoxicosis with fever, tachyarrhythmia, agitation/delirium, GI/hepatic dysfunction (Burch-Wartofsky score). Treat clinically.", tx: ["ICU; beta-blocker (propranolol) for adrenergic symptoms and to block T4→T3 conversion.","Antithyroid drug — propylthiouracil (preferred in storm) or carbimazole.","Give iodine (Lugol's/potassium iodide) at least 1 h AFTER the antithyroid drug.","Hydrocortisone (reduces T4→T3 and treats relative adrenal insufficiency).","Supportive: cooling, fluids, treat the precipitant (often infection); avoid aspirin."], ix: ["TFTs (don't delay treatment)","ECG, glucose, LFTs","Septic screen"], dispo: "ICU.", src: "Harrison 22e · ATA" },
    seizure_epilepsy: { dx: "Stereotyped paroxysmal event ± post-ictal confusion. First seizure vs known epilepsy; status if >5 min or recurrent without recovery.", tx: ["Status epilepticus: protect airway, O2, glucose; IV lorazepam (or IM midazolam), repeat once.","Second-line: IV levetiracetam, valproate or phenytoin/fosphenytoin.","Refractory status → ICU, intubation, anaesthetic infusion (propofol/midazolam).","Correct provoking causes (hypoglycaemia, hyponatraemia, alcohol, drugs, infection).","First unprovoked seizure: usually no drug; start AED if high recurrence risk / abnormal EEG-MRI; neurology referral, driving advice."], ix: ["Glucose, electrolytes, Ca/Mg","CT/MRI brain, EEG","Drug levels/toxicology"], dispo: "Status → ICU; first seizure → neurology.", src: "Harrison 22e · NICE/AES" },
    vasovagal_syncope: { dx: "Transient LOC with prodrome (warmth, nausea, greying vision), rapid full recovery, typical triggers; orthostatic drop or reflex pattern. Exclude cardiac/structural cause.", tx: ["Reassure once cardiac causes excluded; explain mechanism.","Avoid triggers; ensure hydration and adequate salt intake.","Teach physical counter-pressure manoeuvres (leg crossing, hand grip) at prodrome.","Review/stop hypotensive drugs; treat orthostatic component (compression, slow rising).","ECG ± monitoring to rule out arrhythmia; refer cardiology if exertional/red-flag features."], ix: ["12-lead ECG, lying/standing BP","Bloods (anaemia, glucose)","Tilt-table/ambulatory monitor if uncertain"], dispo: "Outpatient; cardiology if red flags.", src: "Harrison 22e · ESC syncope" },
    anemia_sympt: { dx: "Fatigue, dyspnoea, pallor, tachycardia with low haemoglobin; classify by MCV and look for blood loss/haemolysis.", tx: ["Assess haemodynamic tolerance; transfuse for symptomatic/severe anaemia (restrictive threshold ~70 g/L, ~80 if cardiac).","Identify and treat the cause — iron/B12/folate deficiency, bleeding, haemolysis, marrow, chronic disease.","Iron deficiency: oral iron (IV if intolerant/malabsorption) and find the source (GI evaluation in at-risk).","Replace B12/folate as indicated (give B12 before folate to avoid subacute combined degeneration).","Reticulocyte count and blood film direct further work-up."], ix: ["FBC, MCV, blood film, reticulocytes","Iron studies, B12/folate","Haemolysis screen; source of bleeding"], dispo: "By cause/severity; admit if unstable.", src: "Harrison 22e · AABB transfusion" },
    malignancy_b: { dx: "Constitutional 'B' symptoms (weight loss, fevers, night sweats) ± lymphadenopathy/organomegaly suggesting lymphoma/occult malignancy.", tx: ["Structured work-up: examination, bloods, imaging (CT) and targeted tissue diagnosis (excision/core biopsy).","Avoid empirical steroids before histology (can obscure lymphoma diagnosis).","Refer to the appropriate oncology/haematology MDT promptly.","Definitive treatment is tumour-specific after staging.","Manage symptoms and oncological emergencies (hypercalcaemia, SVCO, cord compression)."], ix: ["FBC, film, LDH, ESR","CT chest/abdo/pelvis ± PET","Tissue biopsy"], dispo: "Urgent oncology/haematology referral.", src: "Harrison 22e" },
    crystal_arthritis: { dx: "Acute monoarthritis (often 1st MTP/knee) — confirm with joint aspiration showing crystals; ALWAYS exclude septic arthritis.", tx: ["Aspirate the joint — crystals confirm gout/pseudogout; Gram stain/culture EXCLUDES septic arthritis.","Acute attack: NSAID, or colchicine, or corticosteroid (oral/intra-articular) — choose by comorbidity.","Rest, ice, analgesia; continue any established urate-lowering therapy through the attack.","Do NOT start/stop allopurinol during an acute flare for the first time; initiate urate-lowering later with prophylaxis.","Address risk factors (diuretics, alcohol, renal function)."], ix: ["Joint aspiration (crystals + culture)","Serum urate (after flare), renal function"], dispo: "Outpatient; admit if septic arthritis not excluded.", src: "Harrison 22e · ACR/EULAR gout" },
    sle_flare: { dx: "Multisystem flare (rash, arthritis, serositis, cytopenias, nephritis) in known/new SLE; raised anti-dsDNA, low complement.", tx: ["Assess organ involvement and severity (esp. renal, CNS, haematological).","Mild: hydroxychloroquine ± short NSAID/low-dose steroid.","Moderate–severe / organ-threatening: high-dose corticosteroids + immunosuppression (mycophenolate/cyclophosphamide; biologics).","Hydroxychloroquine for essentially all patients (reduces flares).","Exclude/treat concurrent infection (mimics flare and complicates immunosuppression); sun protection, vaccination."], ix: ["anti-dsDNA, complement (C3/C4)","FBC, renal function, urinalysis (casts/protein)","Exclude infection"], dispo: "Rheumatology; admit if organ-threatening.", src: "Harrison 22e · EULAR SLE" },
    vasculitis: { dx: "Multisystem illness — purpura, mononeuritis, renal/lung involvement, raised inflammatory markers; ANCA and biopsy guide diagnosis.", tx: ["Assess for organ/life-threatening features (alveolar haemorrhage, active glomerulonephritis — always classed as severe even with normal renal function).","Induce remission of severe ANCA-associated vasculitis with cyclophosphamide OR rituximab plus glucocorticoids; consider adjunctive avacopan to reduce steroid exposure.","Reserve plasma exchange for selected cases (concurrent anti-GBM antibody, or controversial use in the most fulminant disease) — a large RCT showed no benefit on the ESRD/death composite, so it is not routine.","Confirm with ANCA and tissue biopsy; exclude infection/mimics before immunosuppression (a rising ANCA alone is not a reason to escalate therapy).","Maintenance immunosuppression after induction; give Pneumocystis (TMP-SMX) prophylaxis plus bone/gastric protection on glucocorticoids."], ix: ["ANCA, complement, urinalysis","Renal function, CXR","Tissue biopsy"], dispo: "Urgent rheumatology/nephrology; admit if organ-threatening.", src: "Harrison 22e · EULAR/KDIGO · rev. Harrison 22e 2898-2946" },
    hyperthyroidism: { dx: "Weight loss, tremor, heat intolerance, palpitations with suppressed TSH and raised free T4/T3 (uncomplicated, no storm).", tx: ["Beta-blocker (propranolol) for symptomatic relief of adrenergic symptoms.","Antithyroid drug — carbimazole (or PTU in 1st-trimester pregnancy).","Determine cause (Graves vs nodular vs thyroiditis) — TRAb, uptake scan.","Discuss definitive options: radioactive iodine or surgery.","Monitor TFTs and FBC/LFTs (agranulocytosis, hepatotoxicity warning)."], ix: ["TFTs, TRAb","Thyroid uptake scan/US","FBC, LFTs baseline"], dispo: "Outpatient endocrinology (admit if storm).", src: "Harrison 22e · ATA" },
    ild: { dx: "Progressive exertional dyspnoea, dry cough, fine bibasal 'velcro' crackles; restrictive spirometry; HRCT pattern.", tx: ["HRCT chest and full PFTs; refer respiratory ILD service / MDT.","Identify cause — drugs, connective-tissue disease, occupational/environmental, hypersensitivity.","Treatment is pattern-specific: immunosuppression for inflammatory ILD; antifibrotics (pirfenidone/nintedanib) for IPF.","Oxygen for hypoxaemia; pulmonary rehabilitation; vaccinations.","Manage comorbidities; consider transplant referral in advanced disease."], ix: ["HRCT chest","PFTs (restrictive, low DLCO)","Autoimmune serology"], dispo: "Respiratory referral.", src: "Harrison 22e · ATS/ERS" },
    pleural_effusion: { dx: "Dyspnoea with stony dull base, reduced breath sounds; CXR/US confirms. Tap to classify (Light's criteria: exudate vs transudate).", tx: ["Diagnostic pleural aspiration (US-guided) — protein, LDH, pH, cytology, microbiology.","Apply Light's criteria; treat the underlying cause (heart failure, malignancy, etc.).","Therapeutic drainage for breathlessness (avoid >1.5 L at once — re-expansion oedema).","Suspected empyema/complicated parapneumonic: chest drain.","Malignant effusion: consider indwelling pleural catheter or pleurodesis."], ix: ["Pleural US + diagnostic tap","Light's criteria, cytology","Identify primary cause"], dispo: "Admit if large/symptomatic or infected.", src: "Harrison 22e · BTS pleural" },
    tamponade: { dx: "Hypotension, raised JVP, muffled heart sounds (Beck's triad) with pulsus paradoxus; echo shows effusion with diastolic collapse.", tx: ["EMERGENCY — urgent echo; cardiology/cardiothoracic input.","Echo-guided pericardiocentesis (or surgical drainage) to relieve tamponade.","IV fluids as a temporising measure to maintain filling.","Avoid positive-pressure ventilation if possible until drained.","Treat and investigate the underlying cause; send pericardial fluid for analysis."], ix: ["Urgent echo","ECG (low voltage/alternans)","Pericardial fluid analysis"], dispo: "ICU + pericardiocentesis.", src: "Harrison 22e · ESC pericardial" },
    htn_emergency: { dx: "Severe hypertension (often >180/120) WITH acute target-organ damage (encephalopathy, ACS, pulmonary oedema, AKI, retinopathy, dissection).", tx: ["Confirm target-organ damage (distinguishes emergency from urgency).","Controlled IV BP reduction — lower MAP by ~20–25% in the first hour (not to normal), titratable agent (labetalol, nicardipine, GTN).","Tailor target/agent to the syndrome (faster + lower in dissection/pulmonary oedema; cautious in acute stroke).","ICU/HDU monitoring with arterial line.","Identify cause; transition to oral agents once stable."], ix: ["Fundoscopy","ECG, troponin, U&E","CT head/CXR as indicated"], dispo: "ICU/HDU.", src: "Harrison 22e · ESC/ACC HTN" },
    glomerulonephritis: { dx: "Haematuria (dysmorphic RBCs/casts), proteinuria, hypertension ± AKI. Rapidly progressive GN is an emergency.", tx: ["Assess for rapidly progressive GN (rising creatinine) — nephrology emergency; urgent biopsy.","Send immunology (ANCA, anti-GBM, complement, ANA) before immunosuppression.","RPGN: high-dose corticosteroids + cyclophosphamide/rituximab ± plasma exchange (anti-GBM/severe).","Supportive: BP control (ACEi/ARB), manage fluid/electrolytes, treat any infection trigger.","Treat the specific cause; monitor renal function closely."], ix: ["Urinalysis + microscopy (casts)","Renal function, immunology panel","Renal biopsy"], dispo: "Admit; nephrology.", src: "Harrison 22e · KDIGO GN" },
    toxic_hepatitis: { dx: "Acute transaminitis ± jaundice temporally linked to a drug/toxin (esp. paracetamol). Assess for acute liver failure (INR, encephalopathy).", tx: ["Stop the offending drug/toxin immediately.","Paracetamol overdose: N-ACETYLCYSTEINE (use the nomogram / treat if staggered or uncertain timing).","Supportive care; monitor INR, glucose, lactate, creatinine and mental status for acute liver failure.","Contact a liver/transplant unit early if ALF criteria (rising INR, encephalopathy, acidosis) — King's College criteria.","Avoid further hepatotoxins; treat complications (coagulopathy, hypoglycaemia, cerebral oedema)."], ix: ["LFTs, INR, paracetamol level","Glucose, lactate, ABG, creatinine","Liver screen"], dispo: "Admit; ALF → transplant centre/ICU.", src: "Harrison 22e · AASLD ALF" },
    ibd_flare: { dx: "Bloody diarrhoea, urgency, abdominal pain ± systemic features in known/new IBD; raised CRP/faecal calprotectin; exclude infection (incl. C. difficile).", tx: ["EXCLUDE infective colitis (stool culture + C. difficile toxin) before/with immunosuppression.","Acute severe UC: admit, IV corticosteroids, VTE prophylaxis, monitor (Truelove-Witts / day-3 response).","Steroid-refractory severe UC: rescue ciclosporin or infliximab; early surgical review (colectomy).","Crohn's flare: corticosteroids to induce remission; optimise/escalate maintenance (immunomodulator/biologic).","Avoid antimotility agents in severe colitis (toxic megacolon risk); nutrition support."], ix: ["CRP, FBC, albumin, faecal calprotectin","Stool culture + C. diff","AXR (toxic megacolon), flexi-sig"], dispo: "Admit if severe; gastroenterology + surgery.", src: "Harrison 22e · ECCO/BSG IBD" },
    ttp_hus: { dx: "Microangiopathic haemolytic anaemia + thrombocytopenia (± renal failure, neuro signs, fever). Schistocytes on film; ADAMTS13 in TTP.", tx: ["HAEMATOLOGICAL EMERGENCY — urgent haematology referral.","TTP: start PLASMA EXCHANGE immediately (don't wait for ADAMTS13) + corticosteroids; add caplacizumab/rituximab.","Do NOT transfuse platelets unless life-threatening bleeding (may worsen thrombosis).","HUS: supportive care, renal support; eculizumab for atypical/complement-mediated HUS.","Monitor LDH, platelets, haemoglobin and organ function."], ix: ["FBC + blood film (schistocytes)","LDH, haptoglobin, bilirubin, reticulocytes","ADAMTS13, renal function, coagulation"], dispo: "Admit; ICU/haematology, urgent.", src: "Harrison 22e · BSH/ISTH" },
    gbs: { dx: "Progressive ascending weakness with areflexia ± sensory/autonomic involvement, often post-infective; albuminocytological dissociation on CSF; supportive NCS.", tx: ["ADMIT — monitor respiratory function (serial FVC) and autonomic status closely.","IVIG 0.4 g/kg/day ×5 days OR plasma exchange (equivalent efficacy).","ICU + ventilation if FVC falling, bulbar weakness or autonomic instability.","VTE prophylaxis, pain control, physiotherapy, pressure-area care.","Do NOT give corticosteroids (ineffective in GBS)."], ix: ["Serial spirometry (FVC)","LP (albuminocytological dissociation)","Nerve conduction studies"], dispo: "Admit; ICU if respiratory/autonomic compromise.", src: "Harrison 22e" },
    myasthenic_crisis: { dx: "Worsening bulbar/respiratory weakness in myasthenia gravis (or new presentation) with respiratory failure; often triggered by infection/drugs.", tx: ["ADMIT to ICU; monitor FVC/NIF — intubate early for respiratory failure.","IVIG or plasma exchange for the crisis.","Identify and remove triggers (infection, aminoglycosides, beta-blockers, magnesium).","Hold/adjust pyridostigmine acutely (secretions); optimise immunotherapy (steroids ± steroid-sparing) once stabilising.","Steroids may transiently worsen weakness — start cautiously under specialist care."], ix: ["FVC/NIF","Anti-AChR/MuSK antibodies","Septic screen, drug review"], dispo: "ICU + neurology.", src: "Harrison 22e" },
    cord_compression: { dx: "Bilateral leg weakness, a sensory level, and bladder/bowel dysfunction ± back pain. Urgent whole-spine MRI.", tx: ["EMERGENCY — urgent whole-spine MRI; immobilise if traumatic/unstable.","High-dose dexamethasone for malignant compression (with PPI).","Emergency referral to spinal surgery / oncology for decompression ± radiotherapy.","Time-critical: outcome depends on speed — treat within hours.","Bladder care, VTE prophylaxis, analgesia."], ix: ["Whole-spine MRI (urgent)","Identify primary if malignant"], dispo: "Emergency spinal surgery / oncology.", src: "Harrison 22e · NICE MSCC" },
    hhs: { dx: "Marked hyperglycaemia with high osmolality and minimal ketosis/acidosis, profound dehydration ± reduced consciousness (typically older T2DM).", tx: ["Aggressive IV 0.9% saline — fluid replacement is the priority (large deficits, replace gradually).","Low-rate IV insulin, started after fluids (or if ketonaemia/glucose not falling with fluids alone).","Replace potassium guided by levels; monitor osmolality fall (aim gradual to avoid cerebral oedema).","VTE prophylaxis (high thrombotic risk); find and treat the precipitant.","Monitor glucose, Na, K and neuro status closely."], ix: ["Glucose, osmolality, U&E","VBG, ketones","Septic screen, ECG"], dispo: "Admit HDU/ICU.", src: "Harrison 22e · ADA/JBDS HHS" },
    myxedema: { dx: "Severe hypothyroidism with hypothermia, bradycardia, hypoventilation and reduced consciousness ± hyponatraemia; usually a precipitant.", tx: ["ICU; IV levothyroxine (± liothyronine) — give thyroid hormone.","Give IV HYDROCORTISONE first/concurrently (until adrenal insufficiency excluded).","Passive rewarming, ventilatory support for hypoventilation/CO2 retention.","Cautious correction of hyponatraemia and hypoglycaemia; IV fluids.","Treat the precipitant (commonly infection — may be afebrile)."], ix: ["TFTs, cortisol","ABG, glucose, Na","ECG, septic screen"], dispo: "ICU.", src: "Harrison 22e · ATA" },
    pheo: { dx: "Paroxysmal hypertension with headache, sweating, palpitations; raised plasma/urine metanephrines; tumour on imaging.", tx: ["Crisis: control with a titratable agent (IV phentolamine / nicardipine).","Establish ALPHA-blockade FIRST (phenoxybenzamine/doxazosin) — never beta-block before alpha (unopposed alpha → crisis).","Add beta-blockade later for tachyarrhythmia, after adequate alpha-blockade and volume repletion.","Liberal salt/fluid to restore volume pre-operatively.","Definitive: surgical resection after adequate blockade (≈2 weeks); endocrine/surgical MDT."], ix: ["Plasma/24h urine metanephrines","CT/MRI adrenal, MIBG","Genetic screen"], dispo: "Admit; ICU if crisis.", src: "Harrison 22e · Endocrine Society" },
    hypercalcemia: { dx: "Confusion, polyuria, constipation, abdominal pain with raised corrected calcium; PTH distinguishes hyperparathyroidism from malignancy/other.", tx: ["Aggressive IV 0.9% saline rehydration (cornerstone) with monitoring of fluid status.","IV bisphosphonate (e.g. zoledronic acid) for moderate–severe hypercalcaemia (effect over 2–4 days).","Calcitonin for rapid short-term lowering in severe/symptomatic cases.","Avoid thiazides; stop calcium/vitamin D; treat the underlying cause (malignancy, hyperparathyroidism).","Denosumab for bisphosphonate-refractory malignant hypercalcaemia."], ix: ["Corrected calcium, PTH, phosphate","U&E, vitamin D","Malignancy work-up"], dispo: "Admit if symptomatic/severe.", src: "Harrison 22e · Endocrine Society" },
    opioid_od: { dx: "Reduced consciousness, respiratory depression and PINPOINT pupils; response to naloxone is both diagnostic and therapeutic.", tx: ["Support airway and ventilation (bag-mask) — hypoxia kills, not the drug per se.","NALOXONE titrated to adequate respiration (not full arousal) — start low to avoid acute withdrawal.","Repeat naloxone or start an infusion (long-acting opioids outlast a naloxone bolus — re-sedation risk).","Observe for a prolonged period after the last naloxone dose; monitor for pulmonary oedema.","Address the cause; harm reduction, take-home naloxone, addiction referral."], ix: ["Capnography/SpO2, ABG","Glucose, paracetamol/salicylate (co-ingestion)","ECG"], dispo: "Observe; ICU if infusion/intubated.", src: "Harrison 22e" },
    salicylate_tox: { dx: "Tinnitus, hyperventilation, nausea, agitation with a mixed respiratory alkalosis + high-anion-gap metabolic acidosis; rising salicylate level.", tx: ["Resuscitate; correct hypokalaemia and hypoglycaemia (cerebral glucose may be low despite normal serum).","Activated charcoal if early; generous IV fluids.","Urinary alkalinisation with IV sodium bicarbonate (target urine pH ~7.5–8) — enhances elimination; keep K replete.","HAEMODIALYSIS for severe toxicity (high levels, acidosis, CNS features, renal failure, pulmonary oedema).","Avoid intubation if possible (loss of compensatory hyperventilation is dangerous); serial levels."], ix: ["Serial salicylate levels","ABG/VBG, U&E (potassium), glucose","Paracetamol level (co-ingestion)"], dispo: "Admit; severe → ICU/dialysis.", src: "Harrison 22e · poisons service" },
    serotonin_nms: { dx: "Hyperthermia, rigidity and altered mental state with autonomic instability — serotonergic excess (clonus, hyperreflexia, rapid onset) vs NMS (lead-pipe rigidity, antipsychotic, slower).", tx: ["STOP the offending agent immediately (serotonergic drug or antipsychotic).","Aggressive cooling and IV fluids; benzodiazepines for agitation/rigidity; ICU for severe cases.","Serotonin syndrome: consider cyproheptadine. NMS: consider dantrolene ± bromocriptine.","Monitor for and treat rhabdomyolysis, hyperthermia, renal failure and DIC.","Supportive care; avoid restraints worsening hyperthermia."], ix: ["Creatine kinase, U&E, coagulation","Temperature, ECG","Drug history"], dispo: "Admit; ICU if severe/hyperthermic.", src: "Harrison 22e" },
    organophosphate: { dx: "Cholinergic toxidrome — miosis, salivation/lacrimation, bronchorrhoea, bradycardia, fasciculations — after organophosphate/carbamate exposure.", tx: ["Protect staff (PPE) and decontaminate (remove clothing, wash skin).","Secure airway; suction copious secretions — bronchorrhoea/respiratory failure is the killer.","ATROPINE in escalating/doubling doses titrated to drying of secretions and adequate oxygenation (not pupils/HR).","PRALIDOXIME (oxime) for organophosphates with nicotinic features/weakness.","Benzodiazepines for seizures; ICU monitoring (intermediate syndrome, rebound)."], ix: ["Clinical; plasma/RBC cholinesterase","ABG, ECG","Observe for delayed effects"], dispo: "ICU.", src: "Harrison 22e · WHO" },
    dic: { dx: "Bleeding and/or thrombosis with consumptive coagulopathy (low platelets, high PT/APTT, low fibrinogen, high D-dimer) secondary to a trigger (sepsis, malignancy, obstetric).", tx: ["TREAT THE UNDERLYING CAUSE — this is the priority (sepsis, obstetric emergency, malignancy).","Bleeding/high-risk: replace with platelets, fresh frozen plasma, and cryoprecipitate/fibrinogen guided by levels.","Thrombotic phenotype without bleeding: consider therapeutic anticoagulation (specialist-guided).","Supportive care; serial coagulation monitoring.","Haematology involvement."], ix: ["Platelets, PT/APTT, fibrinogen, D-dimer","Blood film","Identify trigger"], dispo: "Admit; ICU + haematology.", src: "Harrison 22e · ISTH/BSH" },
    acute_leukemia: { dx: "Pancytopenia or leucocytosis with blasts on film, bleeding/infection; bone marrow confirms. Watch for tumour lysis/DIC.", tx: ["Urgent haematology referral; admit.","Supportive: transfuse as needed, neutropenic-sepsis protocol for fever, tumour-lysis prophylaxis (hydration, allopurinol/rasburicase).","Treat coagulopathy/DIC (esp. APML — start ATRA promptly on suspicion).","Definitive remission-induction chemotherapy per subtype; consider transplant.","Central access, fertility/consent discussions as appropriate."], ix: ["FBC + blood film, coagulation","Bone marrow + cytogenetics/flow","LDH, urate, U&E (TLS)"], dispo: "Admit; haematology.", src: "Harrison 22e" },
    variceal_bleed: { dx: "Haematemesis/melaena in portal hypertension; haemodynamic compromise. Confirmed and treated at endoscopy.", tx: ["Resuscitate: large-bore IV access; restrictive transfusion (transfuse when Hb <7 g/dL); correct marked coagulopathy/thrombocytopenia before endoscopy.","Give cirrhotic UGIB patients an IV vasoactive drug (octreotide/somatostatin/terlipressin) AND an antibiotic (e.g. ceftriaxone) on presentation — both reduce rebleeding and mortality.","Consider tracheal intubation for airway protection in repeated haematemesis; IV erythromycin ~30-90 min pre-scope to improve visualisation.","Endoscopy within 24 h: variceal band ligation for oesophageal varices, tissue-adhesive injection for gastric varices.","Persistent/recurrent bleeding or advanced liver disease (Child-Pugh B 8-9 with active bleeding, or C 10-13): TIPS; secondary prophylaxis with nonselective beta blocker + band ligation."], ix: ["FBC, coagulation, cross-match, LFTs","Urgent OGD","Lactate"], dispo: "ICU/HDU + gastroenterology.", src: "Harrison 22e · Baveno/AASLD · rev. Harrison 22e 360-362" },
    svc_obstruction: { dx: "Facial/neck/arm swelling, distended veins, dyspnoea ± plethora; usually malignant. CT confirms level/cause.", tx: ["Sit the patient up; oxygen; assess airway (emergency if stridor/cerebral oedema).","CT chest to define cause and obtain tissue diagnosis before treatment where possible.","Endovascular stenting gives rapid relief, esp. for severe symptoms.","Cause-directed therapy: radiotherapy/chemotherapy for malignancy (SCLC/lymphoma chemo-sensitive).","Corticosteroids in steroid-responsive tumours/airway compromise; anticoagulate if thrombus."], ix: ["CT chest with contrast","Tissue diagnosis","Identify primary"], dispo: "Admit; oncology/IR.", src: "Harrison 22e" },
    aki: { dx: "Acute rise in creatinine and/or fall in urine output (KDIGO). Classify pre-renal / renal / post-renal.", tx: ["Assess volume status — fluid resuscitate if pre-renal/hypovolaemic; relieve obstruction (catheter/imaging) if post-renal.","Stop/avoid nephrotoxins (NSAIDs, ACEi/ARB, contrast, aminoglycosides); review drug doses.","Treat the cause (sepsis, obstruction, intrinsic disease); optimise perfusion and avoid both hypo- and hypervolaemia.","Monitor and treat complications — hyperkalaemia, acidosis, fluid overload, uraemia.","Urgent dialysis for refractory hyperkalaemia/acidosis/overload/uraemic complications; nephrology if intrinsic/unclear."], ix: ["U&E, VBG, urinalysis ± microscopy","Renal tract US (obstruction)","Creatine kinase, immunology if intrinsic"], dispo: "Admit; nephrology/ICU if severe.", src: "Harrison 22e · KDIGO AKI" },
    rhabdo: { dx: "Muscle pain/weakness with markedly raised creatine kinase ± myoglobinuria (dark urine) and AKI; common after immobility, trauma, seizures, toxins, statins.", tx: ["Early aggressive IV fluid resuscitation (isotonic saline) to maintain high urine output — cornerstone to prevent AKI.","Monitor and treat hyperkalaemia and other electrolyte/acid-base disturbances; watch calcium/phosphate.","Treat the cause (relieve compression, stop offending drug, control seizures/agitation, manage hyperthermia).","Avoid nephrotoxins; consider urinary alkalinisation in selected cases (controversial).","Dialysis for refractory hyperkalaemia/acidosis/overload; watch for compartment syndrome."], ix: ["Creatine kinase, U&E, calcium/phosphate","Urinalysis (blood without RBCs)","ECG (hyperkalaemia)"], dispo: "Admit; ICU if severe.", src: "Harrison 22e" },
    sjs_ten: { dx: "Painful mucocutaneous rash with blistering/skin detachment and mucosal erosions, usually drug-induced; SJS <10%, TEN >30% body-surface detachment.", tx: ["STOP the culprit drug immediately (single most important step affecting outcome).","Manage like a burn — fluid/electrolyte balance, temperature control, meticulous wound/eye/mucosal care; ideally a burns/specialist unit.","Analgesia, nutrition, infection surveillance (avoid prophylactic antibiotics).","Ophthalmology and urology/gynae input for mucosal involvement; calculate SCORTEN.","Immunomodulation (ciclosporin/IVIG/etanercept) per specialist — evidence evolving."], ix: ["Clinical ± skin biopsy","SCORTEN, electrolytes, cultures","Drug timeline"], dispo: "Admit (burns/ICU); urgent dermatology.", src: "Harrison 22e" },
    tia: { dx: "Transient focal neurological deficit fully resolving (usually <1 h) without infarction on imaging. Risk-stratify (ABCD2) and image vasculature.", tx: ["Start aspirin 300 mg immediately (then secondary prevention).","Short-term dual antiplatelet (aspirin + clopidogrel) for ~21 days in high-risk TIA/minor stroke.","Urgent assessment (specialist within 24 h); carotid imaging — endarterectomy if symptomatic high-grade stenosis.","Anticoagulate if AF; high-intensity statin; control BP, diabetes, smoking.","Driving advice."], ix: ["MRI/CT brain, carotid Doppler","ECG ± prolonged monitoring (AF)","Lipids, glucose"], dispo: "Urgent TIA clinic / admit if crescendo.", src: "Harrison 22e · AHA/ASA" },
    subdural: { dx: "Headache, fluctuating consciousness or cognitive decline, sometimes after (minor) trauma — esp. elderly/anticoagulated. CT shows crescentic collection.", tx: ["Non-contrast CT head; neurosurgical referral.","Reverse anticoagulation; correct coagulopathy.","Surgical evacuation (burr hole for chronic, craniotomy for acute) if symptomatic/large with mass effect.","Small asymptomatic collections: observe with repeat imaging.","Manage raised ICP; seizure precautions."], ix: ["Non-contrast CT head","Coagulation profile"], dispo: "Neurosurgery referral.", src: "Harrison 22e" },
    wernicke: { dx: "Confusion, ophthalmoplegia/nystagmus, ataxia — esp. alcohol misuse or malnutrition. Clinical diagnosis; treat empirically, don't wait for tests.", tx: ["Give IV THIAMINE BEFORE any glucose (glucose first can precipitate/worsen Wernicke).","High-dose IV thiamine (e.g. 500 mg tds for 2–3 days, then taper) — Pabrinex regimens.","Correct magnesium (cofactor) and other deficiencies; rehydrate.","Treat the underlying cause; alcohol withdrawal management.","Continue oral thiamine after the acute course."], ix: ["Clinical diagnosis","Glucose, magnesium, electrolytes","MRI if uncertain (do not delay treatment)"], dispo: "Admit.", src: "Harrison 22e · EFNS" },
    ms: { dx: "Neurological symptoms disseminated in time and space in a young adult; MRI white-matter lesions, oligoclonal bands. Confirm relapse vs pseudo-relapse (exclude infection/heat).", tx: ["Exclude infection/fever (pseudo-relapse) before treating.","Acute disabling relapse: high-dose corticosteroids (IV/oral methylprednisolone ~3–5 days).","Plasma exchange for severe steroid-refractory relapse.","Disease-modifying therapy decided by neurology (relapse rate/MRI activity).","Symptomatic care (spasticity, bladder, fatigue) and rehabilitation."], ix: ["MRI brain/cord","CSF oligoclonal bands","Exclude infection"], dispo: "Neurology referral.", src: "Harrison 22e · McDonald criteria" },
    rheumatoid: { dx: "Symmetrical small-joint polyarthritis with early-morning stiffness >30 min; RF/anti-CCP, raised ESR/CRP, erosions.", tx: ["Early referral to rheumatology — 'treat to target' (remission/low disease activity).","Start a DMARD early (methotrexate first-line) ± short-term steroid bridge.","Escalate to combination DMARDs or a biologic/targeted synthetic DMARD if inadequate response.","NSAID for symptom relief; monitor DMARD toxicity (FBC, LFTs).","Manage cardiovascular risk, bone health and vaccination."], ix: ["RF, anti-CCP, ESR/CRP","X-rays of hands/feet","FBC, LFTs baseline"], dispo: "Rheumatology referral.", src: "Harrison 22e · ACR/EULAR RA" },
    pmr: { dx: "Bilateral shoulder/hip girdle pain and stiffness in age >50, raised ESR/CRP, dramatic steroid response. Screen for coexisting GCA.", tx: ["Start prednisone 10-20 mg/day for isolated PMR — a prompt, near-complete response supports the diagnosis.","Taper gradually guided by symptoms and ESR/CRP; recurrent symptoms during tapering occur in the majority, so taper cautiously.","Screen for giant cell arteritis at every visit (headache, jaw/tongue claudication, visual symptoms) as PMR and GCA are a single disease spectrum.","Provide glucocorticoid-related risk management: bone protection (calcium/vitamin D +/- bisphosphonate) and glucose monitoring.","For glucocorticoid-resistant or relapsing disease use an IL-6 receptor inhibitor (sarilumab); methotrexate gives only marginal steroid-sparing benefit."], ix: ["ESR, CRP","Exclude RA/myeloma/myositis (CK)"], dispo: "Outpatient; rheumatology if atypical/relapsing.", src: "Harrison 22e · ACR/EULAR PMR · rev. Harrison 22e 2902-2946" },
    decomp_cirrhosis: { dx: "Ascites, jaundice, encephalopathy or variceal bleed with stigmata of chronic liver disease; LFTs/INR/imaging confirm. Always seek a precipitant.", tx: ["Identify and treat the PRECIPITANT — always do a diagnostic ascitic tap to exclude SBP (treat with IV cefotaxime + albumin if PMN ≥250).","Ascites: salt restriction + spironolactone ± furosemide; large-volume paracentesis with albumin for tense ascites.","Encephalopathy: lactulose ± rifaximin; treat triggers (bleed, infection, constipation, electrolytes).","Variceal bleed: resuscitation, terlipressin, prophylactic antibiotics, urgent endoscopic band ligation.","Avoid nephrotoxins/NSAIDs; nutrition; assess for transplant; manage AKI/HRS."], ix: ["LFTs, INR, ammonia, U&E","Diagnostic ascitic tap (cell count + culture)","USS ± Doppler, endoscopy"], dispo: "Admit; ICU for bleed/grade-3-4 encephalopathy.", src: "Harrison 22e · AASLD/EASL" },
    ibs: { dx: "Chronic abdominal pain related to defecation with altered bowel habit and no alarm features; positive symptom-based (Rome IV) diagnosis after excluding organic disease.", tx: ["Confirm alarm features absent (weight loss, bleeding, anaemia, nocturnal symptoms, onset >50) and basic tests normal.","Diet/lifestyle: regular meals, fibre adjustment, trial of low-FODMAP with dietitian; address triggers.","Symptom-targeted drugs: antispasmodics for pain, laxatives for IBS-C, loperamide for IBS-D.","Low-dose tricyclic or SSRI for pain/global symptoms; psychological therapies (CBT/gut-directed hypnotherapy).","Reassurance and a positive diagnosis; review and safety-net."], ix: ["FBC, CRP, coeliac serology, faecal calprotectin","Exclude organic disease"], dispo: "Outpatient.", src: "Harrison 22e · Rome IV/NICE IBS" },
    ckd: { dx: "Reduced eGFR and/or markers of kidney damage (albuminuria) for >3 months; stage by eGFR/albuminuria (KDIGO).", tx: ["Treat the cause and slow progression: control BP (ACEi/ARB if albuminuric), glycaemic control, SGLT2 inhibitor where indicated.","Reduce cardiovascular risk (statin, lifestyle, smoking cessation); avoid nephrotoxins; dose-adjust drugs.","Manage complications — anaemia (iron ± ESA), CKD-mineral-bone disorder (phosphate, vitamin D), acidosis, hyperkalaemia.","Monitor eGFR/ACR; vaccinate; dietary sodium/protein advice.","Plan renal replacement / transplant and refer nephrology as eGFR declines."], ix: ["eGFR, ACR, U&E","FBC (anaemia), calcium/phosphate/PTH","Renal US"], dispo: "Outpatient; nephrology by stage.", src: "Harrison 22e · KDIGO CKD" },
    nephrotic: { dx: "Heavy proteinuria (>3.5 g/day), hypoalbuminaemia, oedema ± hyperlipidaemia. Identify primary vs secondary cause; biopsy in adults.", tx: ["Quantify proteinuria; renal biopsy in adults to define the lesion (guides specific therapy).","Reduce proteinuria with ACEi/ARB; manage oedema with salt restriction + loop diuretics (cautious).","Statin for hyperlipidaemia; consider VTE prophylaxis (high thrombotic risk, esp. albumin <20–25 g/L).","Cause-specific immunosuppression (e.g. steroids for minimal change) per nephrology.","Treat secondary causes (diabetes, amyloid, drugs, infection); vaccination."], ix: ["Urine protein:creatinine, albumin, lipids","Renal biopsy","Secondary work-up (glucose, immunology, serology)"], dispo: "Nephrology referral.", src: "Harrison 22e · KDIGO GN" },
    itp: { dx: "Isolated thrombocytopenia with otherwise normal counts/film and no alternative cause; bleeding risk relates to platelet count.", tx: ["No/minor bleeding with platelets >20–30: often observe.","Treat if bleeding or very low count: corticosteroids (prednisolone or dexamethasone) ± IVIG for rapid rise.","Life-threatening bleeding: IVIG + IV methylprednisolone + platelet transfusion (and consider TXA).","Second-line: TPO-receptor agonists, rituximab, or splenectomy.","Avoid antiplatelets/anticoagulants; confirm diagnosis (exclude secondary causes)."], ix: ["FBC + blood film","Exclude secondary causes (HIV, HCV, drugs, SLE)","H. pylori where relevant"], dispo: "Outpatient if stable; admit if bleeding/very low.", src: "Harrison 22e · ASH ITP" },
    myeloma: { dx: "CRAB features — hyperCalcaemia, Renal impairment, Anaemia, Bone lesions/pain — with paraprotein and clonal marrow plasma cells.", tx: ["Manage emergencies: hypercalcaemia (fluids + bisphosphonate), AKI (hydration, stop nephrotoxins), cord compression, infection.","Bone disease: bisphosphonate (zoledronic acid) + analgesia ± radiotherapy/vertebroplasty.","Refer haematology — definitive therapy is combination anti-myeloma regimens ± autologous stem-cell transplant.","Anaemia support; VTE prophylaxis with immunomodulatory regimens; vaccination/infection prophylaxis.","Confirm with serum/urine electrophoresis, free light chains, marrow and imaging."], ix: ["Serum/urine electrophoresis, free light chains","Calcium, renal function, FBC","Skeletal survey/whole-body MRI/CT, marrow"], dispo: "Haematology referral; admit if emergency.", src: "Harrison 22e · IMWG" },
    lung_cancer: { dx: "Cough, haemoptysis, weight loss, or an incidental mass in a smoker; CT chest and tissue diagnosis with staging.", tx: ["CT chest/abdomen and tissue diagnosis (bronchoscopy/biopsy); PET-CT for staging.","Refer to lung-cancer MDT urgently.","Treatment by type/stage: surgery (early NSCLC), chemoradiotherapy, targeted/immunotherapy by molecular profile; SCLC is chemo-sensitive.","Smoking cessation; manage complications (effusion, SVCO, hypercalcaemia, cord compression).","Early palliative-care involvement improves outcomes."], ix: ["CT chest","Biopsy + molecular markers","PET-CT, brain MRI staging"], dispo: "Urgent oncology/MDT referral.", src: "Harrison 22e · NICE/ESMO" },
    sarcoidosis: { dx: "Multisystem granulomatous disease — bilateral hilar lymphadenopathy, lung infiltrates ± skin/eye/cardiac involvement; non-caseating granulomas on biopsy (exclude TB).", tx: ["Confirm histology (non-caseating granulomas) and EXCLUDE TB/infection/lymphoma first.","Asymptomatic/mild: observe — many resolve spontaneously.","Treat if organ-threatening (cardiac, neuro, eye, progressive lung, hypercalcaemia): corticosteroids first-line.","Steroid-sparing agents (methotrexate/azathioprine) for chronic disease.","Screen for cardiac and ocular involvement; monitor calcium."], ix: ["CXR/HRCT, serum ACE, calcium","Tissue biopsy","ECG/echo, ophthalmology"], dispo: "Respiratory/multispecialty referral.", src: "Harrison 22e · ATS sarcoid" },
    hyponatremia: { dx: "Symptomatic low sodium; assess volume status and serum/urine osmolality to classify (hypovolaemic / euvolaemic-SIADH / hypervolaemic).", tx: ["Severe symptoms (seizures, coma): cautious hypertonic 3% saline boluses to raise Na ~4–6 mmol/L.","Correct slowly: ≤8–10 mmol/L per 24 h (avoid osmotic demyelination); recheck Na frequently.","Hypovolaemic: 0.9% saline. SIADH: fluid restriction ± treat cause. Hypervolaemic: treat HF/cirrhosis, restrict fluid.","Identify and remove the cause (drugs, cortisol/thyroid deficiency, malignancy).","Watch for over-correction — re-lower with dextrose/desmopressin if too fast."], ix: ["Serum + urine osmolality, urine Na","Volume assessment","TFTs, cortisol"], dispo: "Admit; severe → HDU/ICU.", src: "Harrison 22e · European hyponatraemia guideline" },
    hyperkalemia: { dx: "Raised serum potassium ± ECG changes (peaked T, wide QRS). Treat urgently if K ≥6.5 or ECG changes.", tx: ["ECG changes / K ≥6.5: IV CALCIUM gluconate to stabilise the myocardium FIRST.","Shift K intracellularly: IV insulin + dextrose, and nebulised salbutamol.","Remove K: stop K-raising drugs, give a potassium binder; loop diuretic if volume-replete.","Dialysis for refractory/severe hyperkalaemia or established renal failure.","Treat the cause (AKI, drugs — ACEi/ARB/K-sparing, acidosis, rhabdo); recheck K."], ix: ["ECG (immediate)","U&E, VBG","Drug review"], dispo: "Admit/monitored area; nephrology if dialysis needed.", src: "Harrison 22e · UK Renal/KDIGO" },
    panic: { dx: "Abrupt episodes of intense fear with somatic symptoms (palpitations, dyspnoea, chest tightness, paraesthesia) peaking within minutes — a diagnosis of exclusion after ruling out organic causes.", tx: ["EXCLUDE organic mimics first (ACS, PE, arrhythmia, hypoglycaemia, thyrotoxicosis) — especially on first presentation.","Acute: calm reassurance, breathing techniques; benzodiazepines only sparingly/short-term if at all.","First-line ongoing treatment: CBT and/or an SSRI/SNRI.","Reduce stimulants (caffeine), alcohol; lifestyle and psychoeducation.","Arrange follow-up and safety-net; screen for depression and substance use."], ix: ["ECG, glucose, TFTs as indicated","Exclude organic disease"], dispo: "Outpatient; psychiatry/psychology referral.", src: "Harrison 22e · NICE anxiety" },
    angioedema_acei: { dx: "Non-pitting swelling of lips/tongue/face/airway WITHOUT urticaria; ACE-inhibitor or hereditary (bradykinin-mediated). Assess airway.", tx: ["Assess and protect the AIRWAY early — low threshold for senior anaesthetic/ENT involvement and early intubation.","Stop the ACE inhibitor permanently.","Bradykinin-mediated angioedema responds poorly to adrenaline/steroids/antihistamines, but give them if any doubt about anaphylaxis.","Hereditary angioedema: specific therapy (C1-esterase-inhibitor concentrate, icatibant).","Observe for delayed/progressive swelling; avoid ACEi/ARB in future."], ix: ["Clinical; airway assessment","C1-inhibitor/C4 if hereditary suspected"], dispo: "Admit/observe; ICU if airway threatened.", src: "Harrison 22e" },
    // ── Enrichment batch (Harrison 22e + society guidelines) — keyed to the render id ──
    ACHALASIA: { name: "Achalasia", class: "non_infective", system: "Gastroenterology",
      dx: "High-resolution oesophageal manometry is diagnostic (absent peristalsis + impaired LES relaxation; Chicago subtypes I–III). Barium swallow shows a dilated oesophagus with distal 'bird's beak' tapering; endoscopy FIRST to exclude pseudoachalasia (tumour at the GOJ).",
      tx: ["Confirm with manometry and EXCLUDE pseudoachalasia (endoscopy ± EUS/CT) before treating.",
        "Definitive therapy disrupts the LES — graded PNEUMATIC DILATION, laparoscopic HELLER MYOTOMY (+ partial fundoplication), or PER-ORAL ENDOSCOPIC MYOTOMY (POEM); choose by subtype, age and surgical risk (POEM favoured for type III / spastic).",
        "Poor procedure candidates: endoscopic BOTULINUM TOXIN into the LES (temporary, repeatable) as a bridge / palliative option.",
        "Nitrates or calcium-channel blockers (e.g. nifedipine) only when procedures are unsuitable — modest, short-lived benefit.",
        "Treat post-treatment reflux with a PPI; surveil for symptom recurrence and the small long-term squamous-carcinoma risk."],
      ix: ["High-resolution oesophageal manometry (diagnostic + subtype)", "Upper endoscopy to exclude pseudoachalasia", "Barium / timed barium swallow", "Chagas serology if relevant exposure"],
      dispo: "Outpatient GI referral; manometry/endoscopy-guided definitive therapy.", src: "Harrison 22e · ACG / Chicago Classification v4.0" },
    antiphospholipid_syndrome: { name: "Antiphospholipid Syndrome", class: "non_infective", system: "Rheumatology",
      dx: "Persistent antiphospholipid antibodies (lupus anticoagulant, anticardiolipin and/or anti-β2GPI) on ≥2 occasions ≥12 weeks apart PLUS thrombosis or defined pregnancy morbidity; classify with the 2023 ACR/EULAR criteria.",
      tx: ["Acute thrombosis: heparin/LMWH then WARFARIN to INR 2–3 (higher target and/or add antiplatelet for arterial or recurrent events); anticoagulation is usually INDEFINITE for definite APS.",
        "AVOID direct oral anticoagulants (DOACs) — higher recurrence, especially in triple-positive or arterial APS.",
        "Obstetric APS: LOW-DOSE ASPIRIN + prophylactic LMWH through pregnancy (therapeutic LMWH if prior thrombosis); do NOT use warfarin/DOACs in pregnancy.",
        "Asymptomatic aPL carriers / SLE: consider low-dose aspirin ± hydroxychloroquine and aggressive cardiovascular risk-factor control.",
        "CATASTROPHIC APS (CAPS): medical emergency — triple therapy (anticoagulation + high-dose glucocorticoids + plasma exchange and/or IVIG), treat the precipitant (often infection); consider rituximab/eculizumab if refractory."],
      ix: ["LA, anticardiolipin, anti-β2GPI (IgG/IgM); repeat ≥12 weeks", "FBC (thrombocytopenia), renal function, coagulation", "Imaging of the thrombotic territory; screen for SLE"],
      dispo: "Haematology / rheumatology; CAPS → ICU.", src: "Harrison 22e · 2023 ACR/EULAR APS criteria · ISTH" },
    // ── Wave 1 (Cardiology/Cardiovascular + ARDS/derm) — Harrison 22e + guidelines, verified ──
    "congenital_heart_disease": { name: "Adult Congenital Heart Disease", class: "non_infective", system: "Cardiology", dx: "Confirm with transthoracic echocardiography – defines the anatomical lesion, shunt direction/magnitude, chamber size, ventricular function and estimated pulmonary artery pressure. Supplement with cardiac MRI/CT for complex anatomy or RV quantification, and cardiac catheterisation when haemodynamics (Qp:Qs, pulmonary vascular resistance) or coronary anatomy are needed.", tx: ["Refer all but the simplest lesions to a specialist ACHD centre for anatomy-specific, MDT-led planning – risk-stratify by lesion, ventricular function and pulmonary vascular resistance (PVR).","Close haemodynamically significant left-to-right shunts (ASD/VSD/PDA) by transcatheter device or surgery when RV volume overload or symptoms are present and PVR is not prohibitive – do NOT close in established Eisenmenger physiology.","Relieve obstructive/cyanotic lesions per anatomy – coarctation stent/surgery, tetralogy of Fallot repair, pulmonary/aortic valve intervention; reintervene for residual gradients, significant regurgitation or RV–PA conduit dysfunction.","Treat sequelae medically – arrhythmia (rate/rhythm control, catheter ablation, anticoagulation for atrial arrhythmia/intracardiac thrombus) and heart failure (guideline-directed therapy, diuretics); give endocarditis prophylaxis only to high-risk groups (prosthetic valve/material, prior IE, unrepaired cyanotic disease, first 6 months after repair with prosthetic material).","For PAH/Eisenmenger start advanced PAH therapy – endothelin-receptor antagonists (e.g. bosentan/ambrisentan), PDE5 inhibitors, then prostacyclin analogues (avoid calcium-channel blockers); correct iron deficiency, avoid volume depletion and routine venesection.","Special populations – pre-conception counselling and joint ACHD–obstetric care (mWHO risk class); pregnancy contraindicated in severe PAH/Eisenmenger and severe left-heart obstruction – avoid ACE inhibitors/ARBs (and endothelin antagonists) in pregnancy."], ix: ["Transthoracic echocardiography with Doppler – lesion definition, shunt, chamber size, ventricular function, PA pressure","ECG – rhythm, conduction disease, chamber hypertrophy","Cardiac MRI (or CT) – complex anatomy, RV volume/function, aorta, conduits","Cardiopulmonary exercise testing and pulse oximetry – functional capacity, cyanosis/desaturation","Cardiac catheterisation with Qp:Qs and PVR – haemodynamics before shunt closure or when PAH suspected"], dispo: "Specialist ACHD centre with MDT (ACHD cardiologist, congenital surgeon/interventionalist, PAH and obstetric input); lifelong structured follow-up.", src: "Harrison 22e · 2020 ESC Guidelines for the management of adult congenital heart disease" },
    "aortic_regurgitation": { name: "Aortic Regurgitation", class: "non_infective", system: "Cardiology", dx: "Transthoracic echocardiography is the diagnostic standard – confirms the regurgitant jet, grades severity (vena contracta, regurgitant volume/fraction, effective regurgitant orifice, holodiastolic flow reversal in the descending aorta, pressure half-time) and quantifies LV size/function. Suspect clinically from an early diastolic decrescendo murmur at the left sternal edge with wide pulse pressure and collapsing (water-hammer) pulse; acute severe AR presents as sudden cardiogenic pulmonary oedema/shock with tachycardia and a soft, short murmur, without these peripheral signs.", tx: ["Acute severe AR (endocarditis, aortic dissection, trauma) – surgical emergency: stabilise with IV vasodilator (nitroprusside) +/- inotrope (dobutamine); AVOID intra-aortic balloon pump (worsens AR). Beta-blockers are generally avoided because they blunt the compensatory tachycardia, EXCEPT that in type A aortic dissection shear/HR/BP control may still be required under surgical guidance. Arrange emergency valve (+/- aortic) surgery.","Chronic asymptomatic AR with preserved LV – no drug therapy improves survival or reliably delays surgery; serial surveillance and treat coexistent hypertension with a dihydropyridine CCB or ACE inhibitor/ARB.","Definitive treatment is surgical aortic valve replacement (or repair) – refer when symptomatic (any LVEF; Class I), or asymptomatic with LVEF <=55% (ACC/AHA 2020 Class I), or normal EF with marked LV dilatation (LVESD >50 mm or >25 mm/m2; Class IIa).","Aortic root/ascending dilatation (Marfan, bicuspid) – replace the aorta at guideline diameter thresholds even with only mild AR; give beta-blocker and/or ARB (losartan) to slow aortic growth in connective-tissue disease.","Heart failure while awaiting or unfit for surgery – ACE inhibitor/ARB plus diuretic for afterload and volume control; TAVI only in selected inoperable patients (off-label for pure AR).","Manage active infective endocarditis promptly; provide endocarditis prophylaxis only for high-risk patients (prosthetic valve/material, prior IE, specified congenital heart disease, transplant valvulopathy) – native-valve AR alone does not warrant prophylaxis."], ix: ["Transthoracic echocardiography with Doppler – severity, LV dimensions/EF, aortic root.","ECG – LV hypertrophy, strain, conduction disease.","Chest radiograph – cardiomegaly, aortic dilatation, pulmonary congestion.","Cardiac MRI or transoesophageal echo when TTE inconclusive – quantify regurgitant fraction, image aortic root/valve morphology.","CT aortography and blood cultures if dissection or endocarditis suspected; coronary angiography pre-operatively."], dispo: "Refer to cardiology; asymptomatic chronic AR – outpatient surveillance echo; acute severe AR – emergency admission for urgent cardiac surgery.", src: "Harrison 22e · ACC/AHA 2020 Valvular Heart Disease" },
    "bradyarrhythmias": { name: "Bradyarrhythmias & Heart Block", class: "non_infective", system: "Cardiology", dx: "12-lead ECG plus rhythm strip confirms bradycardia (rate <60/min) and localises the lesion – sinus node dysfunction vs AV block (first-degree, Mobitz I/II, high-grade, complete/third-degree with AV dissociation). Correlate symptoms (syncope, presyncope, fatigue, exertional intolerance) with the rhythm; ambulatory or implantable loop monitoring establishes symptom–rhythm correlation when intermittent.", tx: ["Assess haemodynamic stability and treat reversible causes first – stop culprit drugs (beta-blockers, non-dihydropyridine CCBs, digoxin, antiarrhythmics), correct hyperkalaemia/hypothyroidism/hypoxia, manage ischaemia/inferior MI.","Unstable (hypotension, shock, altered mental state, ischaemic chest pain, acute heart failure) – IV atropine 0.5–1 mg boluses (repeat every 3–5 min to max 3 mg) first-line, while preparing pacing.","Atropine-refractory – transcutaneous pacing and/or IV chronotrope infusion (dopamine or adrenaline; isoprenaline as alternative); arrange transvenous temporary pacing as a bridge.","Toxicity-specific antidotes – IV glucagon for beta-blocker overdose, IV calcium ± high-dose insulin-euglycaemia for CCB overdose, digoxin-specific antibody fragments for digoxin toxicity.","Definitive therapy for symptomatic irreversible sinus node dysfunction or acquired Mobitz II / high-grade / third-degree AV block – permanent pacemaker (dual-chamber preferred); consider conduction-system (His/left-bundle) pacing or CRT where a high ventricular pacing burden or LV dysfunction is expected.","Continuous cardiac monitoring until definitive management; refer promptly to cardiology/electrophysiology per ACC/AHA/HRS device indications."], ix: ["12-lead ECG plus continuous telemetry/rhythm strip","Ambulatory monitoring – Holter, external or implantable loop recorder for symptom–rhythm correlation","Electrolytes (K+, Ca2+, Mg2+), renal and thyroid function, plus drug/digoxin levels where relevant","Troponin and ischaemia workup if AV block is acute (assess for inferior MI)","Echocardiography for structural/ischaemic heart disease; electrophysiology study in selected cases"], dispo: "Unstable or high-grade/complete block – admit to monitored bed/CCU with pacing capability and urgent cardiology/EP referral; stable asymptomatic – outpatient cardiology review.", src: "Harrison 22e · ACC/AHA/HRS 2018 Bradycardia & Cardiac Conduction Delay Guideline" },
    "dilated_cardiomyopathy": { name: "Dilated Cardiomyopathy", class: "non_infective", system: "Cardiology", dx: "Confirm with transthoracic echocardiography showing LV dilatation and global systolic dysfunction (LVEF <45%) not explained by abnormal loading conditions or coronary disease. Exclude ischaemic aetiology and screen for reversible/secondary causes before labelling idiopathic or familial DCM.", tx: ["Treat decompensation first – IV loop diuretic for congestion, correct precipitant/arrhythmia, avoid negative inotropes; reserve inotropes/vasopressors and MCS/transplant referral for cardiogenic shock.","Start guideline-directed therapy in all HFrEF (LVEF ≤40%) – ARNI (or ACEi/ARB if unsuitable) + beta-blocker + MRA + SGLT2 inhibitor, uptitrated to target or max-tolerated doses.","Titrate loop diuretic to euvolaemia; consider ivabradine (sinus rate ≥70 on max beta-blocker) and hydralazine–nitrate (self-identified Black patients or RAASi-intolerant).","Correct reversible drivers – rate-control/ablate AF or tachyarrhythmia, alcohol/toxin abstinence, immunosuppression for giant-cell/eosinophilic myocarditis or cardiac sarcoid, repletion of iron/thyroid/thiamine.","Assess devices after ≥3 months optimal GDMT – ICD if LVEF ≤35% (NYHA II–III, survival >1yr); CRT if LVEF ≤35% with LBBB QRS ≥130 ms.","Anticoagulate for AF, prior thromboembolism or LV thrombus; refer to advanced-HF/transplant service for refractory NYHA III–IV or inotrope dependence; offer family screening and genetic counselling in familial DCM."], ix: ["Transthoracic echocardiography – LV size, LVEF, wall motion, thrombus, valvular/RV function.","ECG – conduction disease/LBBB, arrhythmia, low voltages.","Bloods – FBC, U&E, LFTs, TFTs, ferritin/iron studies, glucose/HbA1c, natriuretic peptides (BNP/NT-proBNP).","Coronary angiography or CT coronary angiography to exclude ischaemic aetiology.","Cardiac MRI (fibrosis/infiltration/myocarditis) ± genetic testing and family screening in suspected familial DCM."], dispo: "Manage under cardiology/heart-failure service; admit if decompensated or in cardiogenic shock; early advanced-HF/transplant referral for refractory disease.", src: "Harrison 22e · ESC 2021/2023 Heart Failure Guidelines" },
    "mitral_regurgitation": { name: "Mitral Regurgitation", class: "non_infective", system: "Cardiology", dx: "Confirm with transthoracic echocardiography – define mechanism (primary/degenerative vs secondary/functional), grade severity (vena contracta, EROA, regurgitant volume/fraction) and quantify LV size/EF, LA size and pulmonary pressures. Clinical clue: apical holosystolic murmur radiating to axilla; add transoesophageal echo for repair feasibility and surgical planning.", tx: ["Acute severe MR (papillary muscle/chordal rupture, endocarditis) – stabilise with IV vasodilator (nitroprusside) + loop diuretic to cut afterload/congestion, IABP if hypotensive, then emergency surgery.","Primary severe symptomatic MR – mitral valve repair (preferred over replacement) via Heart Team referral.","Primary severe asymptomatic MR – operate if LVEF ≤60%, LVESD ≥40mm, new AF or PASP >50mmHg; otherwise serial echo surveillance.","Secondary (functional) MR – optimise guideline-directed HF therapy first (ACEi/ARB or ARNI, beta-blocker, MRA, SGLT2i) ± CRT; add transcatheter edge-to-edge repair (TEER) if still symptomatic on maximal therapy with suitable anatomy.","Manage AF – rate/rhythm control plus anticoagulation; relieve congestion with loop diuretics.","No routine endocarditis antibiotic prophylaxis unless prosthetic valve or prior IE."], ix: ["Transthoracic echocardiography – severity, mechanism, LV/LA dimensions, EF, PASP.","Transoesophageal echo – valve anatomy and repair feasibility pre-intervention.","ECG – AF, LA enlargement, LVH.","Chest X-ray – cardiomegaly, pulmonary congestion.","Coronary angiography pre-surgery; cardiac MRI or exercise echo when severity/symptoms discordant; NT-proBNP for monitoring."], dispo: "Cardiology referral with Heart Team evaluation for surgery/TEER; acute severe MR – urgent cardiac surgical centre.", src: "Harrison 22e · ESC/EACTS 2021 VHD" },
    "mitral_stenosis": { name: "Mitral Stenosis", class: "non_infective", system: "Cardiology", dx: "Suspect from apical mid-diastolic rumble, loud S1 and opening snap (usually rheumatic); confirm with transthoracic echocardiography – planimetry/pressure half-time mitral valve area, mean gradient and pulmonary artery pressure. Severe MS = mitral valve area ≤1.5 cm².", tx: ["Control heart rate to prolong diastolic filling and relieve symptoms – beta-blocker or non-dihydropyridine calcium-channel blocker; rate-control new AF, and cardiovert promptly if haemodynamically unstable (ensure anticoagulation/TEE exclusion of thrombus before elective cardioversion).","Relieve pulmonary congestion with loop diuretic and sodium restriction.","Anticoagulate with vitamin K antagonist (INR 2–3) for AF, prior embolism or left atrial thrombus – avoid DOACs in rheumatic MS.","Definitive: percutaneous mitral balloon commissurotomy first-line for symptomatic severe MS with favourable anatomy (Wilkins ≤8), no LA thrombus and ≤mild MR.","Surgical mitral repair/replacement if anatomy unfavourable, PMBC contraindicated, or significant MR/concomitant valve disease.","Secondary rheumatic-fever prophylaxis with long-acting penicillin; in pregnancy use beta-blockade and offer PMBC for refractory severe symptomatic MS."], ix: ["Transthoracic echocardiography – MVA, mean gradient, PASP, Wilkins/splittability score","ECG – atrial fibrillation, P mitrale, RV hypertrophy","Chest X-ray – left atrial enlargement, pulmonary venous congestion","Transoesophageal echo – exclude LA/appendage thrombus and grade MR before intervention","Exercise/stress echo when symptoms discordant with resting haemodynamics"], dispo: "Cardiology referral; symptomatic severe MS to structural/valve heart team for PMBC or surgery.", src: "Harrison 22e · ESC/EACTS" },
    "pericardial_disease": { name: "Pericardial Disease", class: "non_infective", system: "Cardiology", dx: "Acute pericarditis is a clinical diagnosis requiring ≥2 of 4 (ESC 2015): sharp pleuritic chest pain relieved by sitting forward, pericardial friction rub, widespread concave ST-elevation with PR depression on ECG, and new/worsening pericardial effusion. Transthoracic echocardiography confirms effusion, tamponade or constrictive physiology; raised CRP/ESR supports the diagnosis and troponin flags myopericarditis.", tx: ["Emergency – cardiac tamponade (hypotension, raised JVP, pulsus paradoxus, pulsus paradoxus on echo): urgent echo-guided pericardiocentesis; give IV fluids/volume, avoid vasodilators and diuretics (both reduce preload).","First-line acute pericarditis: high-dose NSAID or aspirin (tapered over weeks) PLUS colchicine ×3 months to speed resolution and cut recurrence; add PPI cover and restrict strenuous exertion until symptoms resolve and CRP normalises. Dose colchicine by weight (0.5 mg od if <70 kg, bd if ≥70 kg); reduce or avoid it in significant renal/hepatic impairment and beware CYP3A4/P-gp interactions (macrolides, statins, ciclosporin) which risk severe toxicity. In myopericarditis use lower NSAID doses with stricter exercise restriction; use NSAIDs/aspirin with caution in renal impairment, PUD, heart failure and pregnancy.","Second-line / recurrent or NSAID-contraindicated: add low–moderate dose corticosteroid with colchicine continued ≥6 months (avoid steroids first-line – they increase recurrence); escalate colchicine-resistant recurrent disease to IL-1 blockade (anakinra/rilonacept).","Treat the cause – TB pericarditis (anti-TB + adjunctive corticosteroid), purulent (surgical/urgent drainage + IV antibiotics), uraemic (intensify dialysis), malignant or autoimmune.","Constrictive pericarditis: refer for pericardiectomy; trial anti-inflammatory therapy first only if transient/inflammatory constriction is suspected.","Monitor with serial CRP and echo; refer to cardiology for high-risk, recurrent, large effusive or constrictive disease."], ix: ["ECG – widespread concave ST-elevation with PR depression, evolving through stages","Transthoracic echocardiography – effusion size, tamponade physiology, constriction","Inflammatory/cardiac markers – CRP, ESR, FBC, troponin (myopericarditis)","Chest radiograph – cardiomegaly/water-bottle silhouette, pulmonary or mediastinal cause","Aetiology workup – TB testing (endemic areas), autoimmune serology, blood cultures, renal function; cardiac MRI/CT and pericardial fluid analysis if cause unclear or constriction suspected"], dispo: "Uncomplicated low-risk cases managed as outpatient; admit if high-risk (fever >38°C, subacute onset, large effusion/tamponade, myopericarditis, immunosuppression, oral anticoagulation, or failure to respond to NSAID after ~1 week); tamponade/constriction → urgent cardiology/cardiac surgery.", src: "Harrison 22e · ESC 2015 (pericardial diseases)" },
    "pulmonary_hypertension": { name: "Pulmonary Hypertension", class: "non_infective", system: "Cardiology / Pulmonary", dx: "Suspect on echocardiography — raised tricuspid regurgitant jet velocity, RV dilatation/dysfunction, flattened interventricular septum — in a patient with exertional dyspnoea/fatigue. Confirm and classify by right heart catheterisation: mean pulmonary artery pressure >20 mmHg, distinguishing pre-capillary PH (PAWP ≤15 mmHg and PVR ≥2 WU) from post-capillary PH.", tx: ["Classify into a WHO group first — targeted therapy differs entirely; refer suspected Group 1 (PAH) and Group 4 (CTEPH) to an expert PH centre before starting drugs.","Treat the underlying cause — optimise left-heart disease (Group 2); give long-term oxygen for hypoxaemic lung disease (Group 3); targeted PAH drugs are not indicated and may harm these groups.","Group 1 general measures — diuretics for RV volume overload, supplemental O2 if hypoxaemic, supervised exercise rehab, vaccination; perform acute vasoreactivity testing (idiopathic/heritable/drug-induced) and give high-dose calcium-channel blocker only to confirmed responders.","Group 1 targeted therapy by risk — low/intermediate risk: upfront oral combination endothelin-receptor antagonist (ambrisentan/macitentan) + PDE5 inhibitor (tadalafil/sildenafil) or sGC stimulator (riociguat, never with a PDE5i); high risk: add parenteral prostacyclin analogue (epoprostenol/treprostinil); consider activin-signalling inhibitor sotatercept as add-on.","Group 4 CTEPH — lifelong anticoagulation; assess for pulmonary endarterectomy (potentially curative); if inoperable/residual disease, balloon pulmonary angioplasty and/or riociguat.","Reassess risk every 3–6 months (WHO functional class, 6-min walk, NT-proBNP, echo/haemodynamics); refer for lung transplantation if progressive despite maximal therapy. Pregnancy carries very high mortality — advise against it, avoid ERAs/riociguat (teratogenic), manage at expert centre."], ix: ["Transthoracic echocardiography — TR jet velocity, RV size/function, estimated PASP, septal geometry","Right heart catheterisation — confirms mPAP >20 mmHg, PAWP and PVR; with acute vasoreactivity testing where indicated","V/Q scan — screen for chronic thromboembolic PH (Group 4); CT pulmonary angiography to characterise","Bloods — NT-proBNP/BNP, connective-tissue disease serology (ANA, anti-centromere, Scl-70), HIV, LFTs; ± thrombophilia screen","PFTs with DLCO, overnight oximetry/sleep study, and chest imaging (HRCT) to identify lung-disease and left-heart contributors"], dispo: "Refer to a specialist pulmonary hypertension centre for right heart catheterisation, WHO-group classification and risk-based targeted therapy; manage ongoing care via MDT with regular risk reassessment.", src: "Harrison 22e · ESC/ERS 2022 PH guideline" },
    "cardiovascular_collapse_cardiac_arrest_and": { name: "Cardiovascular Collapse, Cardiac Arrest, and Sudden Cardiac Death", class: "non_infective", system: "cardiovascular", dx: "Clinical diagnosis – unresponsive patient with absent central pulse and apnoea/agonal breathing; confirm within 10 s and start CPR without delaying for tests. Rhythm on the defibrillator/monitor classifies the arrest as shockable (VF/pulseless VT) vs non-shockable (PEA/asystole) to direct the algorithm.", tx: ["Activate resuscitation team; start high-quality CPR – rate 100–120/min, depth 5–6 cm, full recoil, minimise interruptions, rotate compressor every 2 min.","Attach defibrillator: if VF/pulseless VT, shock immediately (biphasic 150–200 J, device-specific) and resume CPR at once; repeat shock every 2 min for persistent shockable rhythm.","Secure airway (do not interrupt compressions), give oxygen, gain IV/IO access – adrenaline 1 mg every 3–5 min (as soon as possible in PEA/asystole; after the 2nd shock in refractory VF/pulseless VT per AHA, or after the 3rd shock per ERC); amiodarone 300 mg then 150 mg for shock-refractory VF/pulseless VT (lidocaine 1–1.5 mg/kg alternative); magnesium 2 g IV for torsades de pointes / polymorphic VT.","Identify and treat reversible causes throughout – 4 Hs (hypoxia, hypovolaemia, hypo-/hyperkalaemia and metabolic/acidosis, hypothermia) and 4 Ts (tamponade, tension pneumothorax, toxins, thrombosis – coronary/pulmonary).","Post-ROSC – 12-lead ECG, targeted temperature management 32–36°C (or active fever avoidance per TTM2), avoid hyperoxia/hypocapnia (SpO₂ 94–98%), maintain MAP (target ≥65 mmHg); urgent coronary angiography ± PCI if STEMI or high cardiac suspicion; admit ICU.","Secondary prevention – ICD for arrest survivors not due to a fully reversible cause and for LVEF ≤35% cardiomyopathy; beta-blocker and guideline-directed HF therapy; treat underlying substrate."], ix: ["Cardiac monitor/rhythm strip – shockable vs non-shockable; 12-lead ECG post-ROSC for STEMI/ischaemia.","ABG with electrolytes (K⁺, Mg²⁺, Ca²⁺), glucose and lactate; troponin.","Bedside echocardiography – tamponade, RV strain (PE), LV function, cardiac standstill.","Point-of-care toxicology/coagulation and CXR as directed by suspected cause.","CT (head/pulmonary) post-ROSC where non-cardiac or embolic cause suspected."], dispo: "Resuscitate in situ, then ICU/CCU admission post-ROSC with early cardiology/electrophysiology referral for cause-directed workup and ICD assessment.", src: "Harrison 22e · AHA/ACC (ACLS 2020) · ERC 2021" },
    "amyloidosis_and_other_restrictive_cardiomy": { name: "Amyloidosis and Other Restrictive Cardiomyopathies", class: "non_infective", system: "Cardiovascular", dx: "Restrictive physiology on echo (non-dilated ventricles, impaired filling, preserved/mildly reduced EF, biatrial enlargement) with increased wall thickness plus low-voltage ECG discordance and apical-sparing longitudinal strain suggests cardiac amyloid. Type the amyloid - exclude AL with serum free light chains + serum/urine immunofixation, and diagnose ATTR non-invasively only when there is grade 2-3 cardiac uptake on 99mTc-PYP/DPD scintigraphy AND a negative monoclonal screen; endomyocardial biopsy (Congo red apple-green birefringence, mass-spectrometry typing) if the monoclonal screen is positive or the scintigraphy is equivocal.", tx: ["Type the amyloid before treating - never assume ATTR without excluding a monoclonal protein (scintigraphy is interpretable only if the light-chain screen is negative); confirm ATTRv vs ATTRwt with TTR gene testing.","Manage congestion with loop diuretics +/- MRA while preserving preload - withdraw/avoid digoxin and calcium-channel blockers (fibril binding, toxicity); use beta-blockers and ACEi/ARB cautiously (often hypotensive/poorly tolerated with fixed stroke volume).","ATTR-CM - start disease-modifying therapy at an amyloid centre: TTR stabiliser (tafamidis or acoramidis) or the CM-approved TTR silencer vutrisiran (HELIOS-B); note patisiran is approved only for hereditary ATTR polyneuropathy, not the cardiomyopathy indication.","AL - urgent haematology referral: suppress the plasma-cell clone with daratumumab-bortezomib-cyclophosphamide-dexamethasone (dara-CyBorD, ANDROMEDA) +/- autologous stem-cell transplant in eligible patients.","Anticoagulate for AF regardless of CHA2DS2-VASc score and screen (TEE) for intracardiac/LAA thrombus before cardioversion; pace symptomatic conduction disease; consider ICD and heart (+/- liver for ATTRv) transplant in selected refractory cases.","Non-amyloid RCM - treat the cause: immunosuppression (sarcoid), phlebotomy/chelation (haemochromatosis), enzyme replacement (Fabry), corticosteroids (eosinophilic/Loffler endocarditis)."], ix: ["ECG - low QRS voltage with pseudo-infarct pattern and conduction disease.","Transthoracic echo with global longitudinal strain - restrictive filling, thickened walls, relative apical sparing ('cherry on top').","Serum free light chains + serum/urine immunofixation electrophoresis - exclude/confirm AL (must be negative to call ATTR non-invasively).","99mTc-PYP/DPD/HMDP bone scintigraphy - Perugini grade 2-3 uptake with a negative monoclonal screen confirms ATTR-CM.","Cardiac MRI (diffuse subendocardial/transmural LGE, raised native T1/ECV) plus NT-proBNP and troponin for staging; endomyocardial biopsy if the non-invasive workup is inconclusive or equivocal."], dispo: "Refer to a specialist cardiac amyloidosis/cardiomyopathy centre; AL amyloid needs urgent haematology co-management.", src: "Harrison 22e - ESC 2023 Cardiomyopathies; Gillmore non-invasive ATTR criteria; ANDROMEDA/ATTR-ACT/ATTRibute-CM/HELIOS-B" },
    "atrial_myxoma_and_other_cardiac": { name: "Atrial Myxoma and Other Cardiac Tumors", class: "non_infective", system: "Cardiovascular", dx: "Confirm with transthoracic echocardiography as first-line, supplemented by transoesophageal echo (size, attachment, mobility) and cardiac MRI for tissue characterisation to distinguish benign myxoma from malignant tumour. Definitive diagnosis is histological after surgical resection.", tx: ["Refer urgently to cardiothoracic surgery – prompt complete surgical excision is first-line and curative for atrial myxoma given high embolic/obstructive risk; do not delay.","Stabilise acute complications – treat heart failure/pulmonary oedema from mitral-inflow obstruction and manage systemic/cerebral embolism via stroke pathway; anticoagulation does not substitute for excision.","Excise with a margin of interatrial septum and repair the defect – recurrence <5% in sporadic disease, higher in familial/Carney complex.","Papillary fibroelastoma and other benign tumours – excise if left-sided, mobile or symptomatic (embolic risk); small asymptomatic right-sided lesions may be surveyed.","Malignant tumours (angiosarcoma) – resect where feasible plus adjuvant chemotherapy/radiotherapy via cardio-oncology MDT (largely palliative); for metastatic disease treat the primary and drain symptomatic pericardial effusion/tamponade.","Screen for Carney complex (PRKAR1A) if young, multiple, recurrent or familial – genetic counselling, echo surveillance of first-degree relatives, and lifelong post-op surveillance echocardiography."], ix: ["Transthoracic echocardiography – first-line imaging","Transoesophageal echocardiography – define size, attachment and mobility","Cardiac MRI – tissue characterisation, benign vs malignant","Bloods: FBC (anaemia), ESR/CRP, IL-6 (raised in myxoma)","Histology of resected specimen – definitive diagnosis"], dispo: "Urgent cardiology and cardiothoracic surgery referral; manage in a centre with advanced cardiac imaging and cardiac surgical capability.", src: "Harrison 22e · ESC/EACVI multimodality imaging of cardiac masses consensus" },
    "cardiac_transplantation_and_prolonged_assi": { name: "Cardiac Transplantation and Prolonged Assisted Circulation", class: "non_infective", system: "Cardiovascular", dx: "Not a single diagnosis but a therapeutic pathway for stage D/end-stage heart failure refractory to optimal medical therapy – confirm advanced HF by persistent NYHA III–IV symptoms, recurrent decompensations or inotrope dependence, peak VO2 <12–14 mL/kg/min on cardiopulmonary exercise testing, and elevated filling pressures on right-heart catheterisation. Transplant/MCS candidacy is decided at a multidisciplinary advanced-HF unit after full risk stratification and contraindication screening.", tx: ["Stabilise refractory HF – IV loop diuretics, inotropes (dobutamine/milrinone), treat precipitants; escalate cardiogenic shock to temporary MCS (IABP, Impella, VA-ECMO) as bridge-to-decision.","Refer early to an advanced-HF/transplant centre for candidacy and contraindication assessment (fixed pulmonary hypertension, active infection/malignancy, severe irreversible multi-organ disease, non-adherence, substance misuse).","Durable continuous-flow LVAD as bridge-to-transplant, bridge-to-candidacy or destination therapy – needs warfarin + antiplatelet anticoagulation with driveline-infection and pump-thrombosis surveillance.","Orthotopic heart transplantation is definitive for eligible patients – induction then lifelong maintenance immunosuppression: calcineurin inhibitor (tacrolimus/ciclosporin) + antiproliferative (mycophenolate) + tapering corticosteroid.","Treat rejection promptly – pulsed corticosteroids ± antithymocyte globulin for acute cellular rejection; IVIG/plasmapheresis/rituximab for antibody-mediated; give prophylaxis (co-trimoxazole for PCP, CMV antiviral, antifungal).","Surveil long-term – endomyocardial biopsy/gene-expression profiling for rejection; manage cardiac allograft vasculopathy (statins ± mTOR inhibitor), CNI nephrotoxicity, hypertension, diabetes and post-transplant malignancy/PTLD."], ix: ["Cardiopulmonary exercise test (peak VO2) to quantify functional impairment and prognosis.","Right-heart catheterisation – pulmonary vascular resistance, transpulmonary gradient and reversibility with vasodilators.","Echocardiography ± coronary angiography to define cardiac structure/function and reversible causes.","Immunological workup – ABO/HLA typing and panel-reactive antibody; virology (CMV, EBV, hepatitis, HIV).","End-organ and comorbidity assessment – renal/hepatic function, pulmonary function tests, infection/malignancy screen."], dispo: "Manage at a specialist advanced-heart-failure/transplant and mechanical-circulatory-support centre with lifelong multidisciplinary follow-up.", src: "Harrison 22e · ISHLT" },
    "cardiac_trauma": { name: "Cardiac Trauma", class: "non_infective", system: "Cardiovascular", dx: "Confirm with focused echocardiography (subxiphoid/FAST view) showing pericardial blood, wall-motion abnormality or structural lesion, together with 12-lead ECG and cardiac troponin. Beck's triad (hypotension, muffled heart sounds, raised JVP) with penetrating precordial wound indicates tamponade until proven otherwise.", tx: ["Resuscitate per ATLS – high-flow O2, two large-bore IV lines, blood/balanced crystalloid (favour blood products/permissive hypotension until haemorrhage control), continuous ECG and haemodynamic monitoring.","Penetrating injury with tamponade or peri-arrest – immediate resuscitative (ED) thoracotomy or emergency sternotomy with surgical repair; do not delay for imaging.","Tamponade in a relatively stable patient – echo-guided pericardiocentesis as a temporising bridge to definitive surgical exploration (traumatic hemopericardium clots, so surgery is definitive).","Blunt cardiac injury/myocardial contusion – supportive care with telemetry ≥24–48h; treat arrhythmias and support cardiogenic shock (inotropes, mechanical support; avoid IABP if coexisting traumatic aortic injury).","Structural lesions (septal, valve or free-wall rupture, coronary dissection) – urgent cardiothoracic surgical repair.","Commotio cordis – immediate CPR and defibrillation."], ix: ["12-lead ECG – sinus tachycardia commonest; also arrhythmia, ST-T change, new RBBB","Cardiac troponin I/T","Focused echocardiography (TTE/TEE) or FAST subxiphoid view – pericardial fluid, wall motion, valve/septal injury","Chest X-ray – widened mediastinum, haemo/pneumothorax, enlarged cardiac silhouette","CT chest/aortic angiography if haemodynamically stable to exclude great-vessel injury"], dispo: "Trauma centre/ICU with continuous telemetry; immediate cardiothoracic/trauma surgery for penetrating injury, tamponade or structural damage.", src: "Harrison 22e · EAST" },
    "common_atrial_flutter_and_macroreentrant": { name: "Common Atrial Flutter and Macroreentrant and Multifocal Atrial Tachycardias", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG is diagnostic. Typical (cavotricuspid isthmus-dependent) atrial flutter shows sawtooth flutter waves negative in II/III/aVF at ~300/min, usually with 2:1 AV conduction (ventricular rate ~150). Multifocal atrial tachycardia (MAT) shows >=3 distinct P-wave morphologies with varying P-P/P-R/R-R intervals and atrial rate >100/min; vagal manoeuvres or adenosine transiently slow AV conduction to unmask atrial activity (they do not terminate either arrhythmia).", tx: ["Unstable (hypotension, ischaemia, pulmonary oedema) -> immediate synchronised DC cardioversion; atrial flutter often converts at low energy (~50 J).","Atrial flutter rate control - IV then oral beta-blocker or non-dihydropyridine calcium-channel blocker (diltiazem/verapamil); flutter is frequently rate-control resistant.","Anticoagulate as for atrial fibrillation by CHA2DS2-VASc; give >=3 weeks anticoagulation or TOE to exclude LA thrombus before elective cardioversion, continue >=4 weeks after.","Definitive rhythm control for typical CTI-dependent flutter - cavotricuspid isthmus catheter ablation (first-line, >90% success, low recurrence); alternatively pharmacological cardioversion with ibutilide/dofetilide under continuous ECG/QT monitoring (torsades risk; dofetilide needs renal dose adjustment).","Multifocal AT - treat the underlying illness (hypoxia, COPD exacerbation, sepsis), correct hypokalaemia/hypomagnesaemia, withdraw theophylline; rate-control with verapamil/diltiazem or cautious cardioselective metoprolol (avoid non-selective beta-blockade in bronchospasm) - DC cardioversion is ineffective and digoxin is not useful.","Refer to cardiology/electrophysiology for ablation of atypical scar-related (macroreentrant) flutter and recurrent typical flutter."], ix: ["12-lead ECG (diagnostic - flutter waves vs >=3 P-morphologies), with rhythm strip during vagal manoeuvres/adenosine if uncertain","Serum electrolytes (K+, Mg2+, Ca2+) and renal function","Thyroid function tests","Transthoracic echocardiography - structural heart disease, LA size, LV function","Transoesophageal echo before early cardioversion; ABG/CXR to identify pulmonary precipitants in MAT"], dispo: "Unstable -> resuscitation area with continuous cardiac monitoring; stable -> cardiology/electrophysiology referral for anticoagulation decision and catheter ablation.", src: "Harrison 22e | ESC 2019 SVT guideline" },
    "diseases_of_the_aorta": { name: "Diseases of the Aorta", class: "non_infective", system: "Cardiovascular", dx: "CT angiography of the whole aorta is the reference test for acute aortic syndromes (dissection, intramural haematoma, penetrating ulcer) and for sizing aneurysms; transoesophageal echocardiography confirms proximal (type A) dissection when patient is unstable or contrast is contraindicated. Abdominal ultrasound is used for AAA screening/surveillance and MR angiography for radiation-sparing follow-up.", tx: ["Suspected acute aortic syndrome/dissection – resuscitate, large-bore IV access, opioid analgesia, group-and-crossmatch; expedite CT angiography of the whole aorta.","Anti-impulse control – IV beta-blocker first (labetalol/esmolol) to HR <60, then add vasodilator (GTN or sodium nitroprusside) targeting SBP 100–120 mmHg; never give vasodilator alone (reflex tachycardia worsens shear stress).","Type A (ascending) dissection or ruptured aneurysm – emergency open surgical repair; immediate cardiothoracic/vascular surgery referral.","Uncomplicated type B (descending) dissection – medical anti-impulse therapy with surveillance; TEVAR if complicated (malperfusion, rupture, refractory pain/hypertension).","Aneurysm – elective repair (open or EVAR/TEVAR) at AAA ≥5.5 cm (men) / ≥5.0 cm (women), ascending TAA ≥5.5 cm (≥4.5–5.0 cm in Marfan/bicuspid/heritable disease), rapid growth >0.5 cm/yr, or symptoms.","Long-term – strict BP control (beta-blocker; losartan/ARB in Marfan), high-intensity statin, smoking cessation, and serial imaging surveillance."], ix: ["CT angiography of the whole aorta (dissection/aneurysm; gold standard)","Transthoracic ± transoesophageal echocardiography (proximal dissection, aortic root/valve, pericardial effusion)","Abdominal aortic ultrasound (AAA detection and surveillance)","ECG and troponin (exclude/identify concurrent MI; coronary ostial involvement)","High-sensitivity D-dimer with clinical risk score (ADD-RS) as rule-out adjunct; FBC, U&E, CRP/ESR (aortitis)"], dispo: "Acute aortic syndrome or ruptured aneurysm – emergency admission with immediate cardiothoracic/vascular surgery referral; stable aneurysm – vascular surgery outpatient surveillance.", src: "Harrison 22e · ACC/AHA 2022 Aortic Disease Guideline · ESC 2024" },
    "electrical_storm_and_incessant_ventricular": { name: "Electrical Storm and Incessant Ventricular Tachycardia", class: "non_infective", system: "Cardiovascular", dx: "ECG/telemetry documenting ≥3 discrete episodes of sustained VT, VF, or appropriate ICD therapies within 24 h (electrical storm), or haemodynamically tolerated VT persisting/recurring for ≥12 h despite repeated termination (incessant VT). Interrogate the ICD to confirm true arrhythmia versus inappropriate shocks/oversensing and characterise VT morphology (monomorphic vs polymorphic).", tx: ["Resuscitate per ACLS — immediate defibrillation for VF/pulseless VT, synchronised DC cardioversion for unstable VT; secure airway and continuous monitoring.","Correct reversible triggers — replete K+/Mg2+, treat ischaemia and decompensated HF, withdraw proarrhythmic/QT-prolonging drugs.","First-line drugs — IV amiodarone PLUS beta-blockade (non-selective propranolol or titratable IV esmolol); combination superior to amiodarone alone. Note: in acquired long-QT torsades avoid amiodarone/QT-prolonging agents and treat per the polymorphic pathway below.","Reduce sympathetic drive — deep sedation (propofol), intubate if refractory; escalate to stellate ganglion block / thoracic epidural or cardiac sympathetic denervation.","Optimise device and pacing — reprogramme ICD (extend detection, enable ATP, minimise shocks); overdrive pacing or isoprenaline plus IV magnesium for pause-dependent polymorphic VT/torsades.","Refractory storm — urgent catheter ablation for scar-related monomorphic VT; mechanical support (Impella/VA-ECMO) as bridge; transfer to EP centre. Substrate-tailored: monomorphic scar VT (amiodarone/ablation) vs polymorphic/torsades (magnesium, pacing/isoprenaline, correct QT) vs channelopathy (Brugada — isoprenaline/quinidine; CPVT — beta-blocker + flecainide)."], ix: ["12-lead ECG + continuous telemetry and full ICD interrogation (episode count, morphology, delivered therapies)","Serum K+/Mg2+/Ca2+, renal function ± arterial blood gas","Troponin and ischaemia workup — coronary angiography if ischaemia suspected","Echocardiography — assess LV function and structural substrate","TSH, toxicology/drug levels and review of QT-prolonging medications"], dispo: "Admit to CCU/ICU with continuous monitoring; urgent cardiology/electrophysiology referral and early transfer to a centre with ablation and mechanical-support capability.", src: "Harrison 22e · ESC 2022 (Ventricular Arrhythmias/SCD)" },
    "focal_atrial_tachycardia": { name: "Focal Atrial Tachycardia", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG in tachycardia shows a regular narrow-complex SVT (rate ~100–250/min) with abnormal P-wave morphology differing from sinus and an isoelectric baseline between P waves (distinguishing it from flutter); a warm-up/cool-down pattern is common. Confirm by electrophysiological study with atrial activation/3D mapping; adenosine or vagal manoeuvres usually cause transient AV block that exposes atrial activity without terminating the tachycardia.", tx: ["If haemodynamically unstable – immediate synchronised DC cardioversion (note automatic foci are often resistant).","Acute, stable – vagal manoeuvres or IV adenosine to slow AV conduction and unmask atrial activity (terminates a minority).","Acute rate/rhythm control – IV beta-blocker or non-dihydropyridine CCB (verapamil/diltiazem); escalate to IV flecainide/propafenone or amiodarone if refractory.","Definitive first-line for recurrent, incessant or tachycardiomyopathy-causing AT – catheter ablation (ESC Class I).","Chronic drug therapy if ablation declined/unsuitable – beta-blocker or verapamil/diltiazem (IIa); add flecainide/propafenone only if no structural or ischaemic heart disease. Avoid digoxin, sotalol, amiodarone and disopyramide for chronic suppression.","Pregnancy – beta-1-selective blocker (metoprolol) or verapamil first-line, flecainide/propafenone if needed; defer ablation (fluoroless if unavoidable). Correct reversible triggers – electrolytes, thyroid, digoxin toxicity."], ix: ["12-lead ECG during tachycardia and in sinus rhythm – P-wave axis/morphology localises the focus","Ambulatory/Holter or event monitor to capture paroxysms and burden","Transthoracic echocardiography – structural disease and LV function (tachycardiomyopathy)","Bloods – electrolytes, magnesium, TFTs, and digoxin level where relevant","Electrophysiological study with 3D activation mapping – diagnostic and therapeutic"], dispo: "Outpatient cardiology; refer to electrophysiology for catheter ablation if recurrent, incessant or causing tachycardiomyopathy — admit if haemodynamically unstable.", src: "Harrison 22e · ESC (2019 SVT)" },
    "genetic_cardiomyopathies": { name: "Genetic Cardiomyopathies", class: "non_infective", system: "Cardiovascular", dx: "Confirm the structural phenotype (hypertrophic, dilated/non-dilated LV, arrhythmogenic RV or biventricular, or restrictive) with echocardiography plus cardiac MRI with late gadolinium enhancement, supported by 12-lead ECG and a detailed three-generation family pedigree. Establish genetic aetiology by proband gene-panel testing within a multidisciplinary inherited-cardiac-conditions service, then cascade clinical and genetic screening of first-degree relatives.", tx: ["Stabilise acute decompensation/arrhythmia, then treat by phenotype. For the dilated/non-obstructive HFrEF phenotype give full GDMT (ARNI or ACEi/ARB, beta-blocker, MRA, SGLT2i); avoid these vasodilators plus nitrates, aggressive diuresis and digoxin in OBSTRUCTIVE HCM as they worsen LVOT obstruction.","Obstructive HCM - negative inotropes: non-vasodilating beta-blocker first-line; if ineffective/not tolerated use verapamil (caution/avoid with severe resting gradient, hypotension or decompensated HF); disopyramide as an add-on to a beta-blocker or verapamil (not as monotherapy). Add cardiac myosin inhibitor mavacamten (needs serial LVEF/echo monitoring, CYP2C19 awareness, teratogenic). Septal myectomy (preferred) or alcohol septal ablation if drug-refractory.","Risk-stratify for SCD (LGE burden, HCM Risk-SCD score, and gene/phenotype-specific risk models in LMNA, ARVC, and other arrhythmogenic genotypes e.g. FLNC/PLN/DSP). ICD for ALL secondary prevention (prior arrest/sustained VT) and for high primary-prevention risk, with lower thresholds in ARVC/LMNA.","Manage arrhythmia - beta-blockers/antiarrhythmics and catheter ablation as indicated; anticoagulate AF in HCM regardless of CHA2DS2-VASc score (DOAC preferred).","Individualise exercise counselling: strict avoidance of competitive/endurance sport in ARVC (accelerates disease); for HCM and other phenotypes allow recreational and selected competitive activity after full evaluation and shared decision-making. Give disease-specific therapy for phenocopies (enzyme replacement/migalastat in Fabry, tafamidis in hereditary ATTR amyloidosis).","Refer for genetic counselling with cascade family screening; assess advanced HF for transplant/LVAD; provide pre-pregnancy counselling (high risk in LMNA, peripartum and desmosomal disease) and note that ARNI/ACEi/ARB, MRA, SGLT2i and mavacamten are contraindicated/avoided in pregnancy."], ix: ["12-lead ECG - LVH, low voltage/conduction disease, epsilon waves or T-wave inversion give aetiological clues.","Transthoracic echocardiography - hypertrophy, dilatation, LVOT gradient (rest and provoked), diastolic function.","Cardiac MRI with LGE and T1 mapping - fibrosis, tissue characterisation, phenocopy detection.","Genetic testing of proband plus three-generation pedigree within an inherited-cardiac-conditions service.","Ambulatory (Holter) ECG for arrhythmia/SCD risk; NT-proBNP/troponin; exercise testing where indicated."], dispo: "Specialist multidisciplinary inherited-cardiac-conditions/cardiomyopathy clinic with genetic counselling; advanced HF unit for device/transplant assessment.", src: "Harrison 22e; ESC 2023 (Cardiomyopathies); AHA/ACC 2024 (HCM)" },
    "heart_failure_management": { name: "Heart Failure: Management", class: "non_infective", system: "Cardiovascular", dx: "Clinical syndrome of dyspnoea, fatigue and fluid retention plus objective cardiac dysfunction — confirm with raised BNP/NT-proBNP and transthoracic echo, classifying by LVEF into HFrEF (<=40%), HFmrEF (41-49%) or HFpEF (>=50%). Establish aetiology (ischaemic, valvular, hypertensive, arrhythmic) and identify the decompensation precipitant.", tx: ["Acute decompensation – sit upright, O2/NIV only if hypoxaemic (SpO2 <90%), IV loop diuretic (furosemide) for congestion, IV nitrate if hypertensive/flash pulmonary oedema (avoid if hypotensive); reserve inotropes/vasopressors for cardiogenic shock and refer for mechanical support. Do NOT initiate or up-titrate beta-blocker during active decompensation.","HFrEF – start guideline-directed quadruple therapy early once stabilised: ARNI (or ACEi/ARB) + beta-blocker + MRA + SGLT2 inhibitor; up-titrate to target or maximally tolerated doses. Initiate/up-titrate beta-blocker only when euvolaemic and haemodynamically stable; allow a 36-h washout when switching ACEi->ARNI (angioedema) and never combine ACEi with an ARB or ARNI.","Add loop diuretic for congestion; if still symptomatic consider ivabradine (sinus rhythm, resting HR >=70 on max-tolerated beta-blocker), hydralazine-nitrate (esp. Black patients or ACEi/ARB-intolerant), digoxin (narrow therapeutic index — reduce/monitor in renal impairment and elderly), or vericiguat.","Device therapy – ICD for primary prevention if LVEF <=35% despite >=3 months optimal therapy (Class I ischaemic, IIa non-ischaemic); CRT if LVEF <=35% with LBBB and QRS >=130 ms (strongest benefit >=150 ms); advanced/refractory HF – refer for LVAD or transplant.","HFpEF/HFmrEF – SGLT2 inhibitor for all; diuretic for congestion; treat hypertension, AF and comorbidities.","Monitor U&E/eGFR and K+ after each initiation/up-titration (hyperkalaemia risk with ARNI/ACEi+MRA); salt/fluid moderation, daily weights, treat precipitants, vaccinate, cardiac rehab; anticoagulate if AF (per CHA2DS2-VASc) and correct iron deficiency.","Pregnancy – ACEi/ARB/ARNI, MRA, SGLT2i, ivabradine and vericiguat are teratogenic/contraindicated; suspected peripartum cardiomyopathy requires specialist cardio-obstetric care using pregnancy-safe agents (beta-blocker, hydralazine-nitrate, loop diuretic; bromocriptine may be considered)."], ix: ["BNP or NT-proBNP","12-lead ECG","Transthoracic echocardiogram – LVEF, chamber size, valves, diastolic function","Bloods – FBC, U&E/eGFR, LFTs, TFTs, glucose/HbA1c, iron studies (ferritin + transferrin saturation)","CXR; consider coronary angiography/CT coronary and cardiac MRI where aetiology unclear"], dispo: "Acute pulmonary oedema/cardiogenic shock – admit (HDU/CCU); stable chronic HF – specialist HF clinic for GDMT up-titration and multidisciplinary follow-up.", src: "Harrison 22e · ESC 2021 (2023 focused update) Heart Failure Guidelines" },
    "heart_failure_pathophysiology_and_diagnosi": { name: "Heart Failure: Pathophysiology and Diagnosis", class: "non_infective", system: "Cardiovascular", dx: "Clinical syndrome of congestion/hypoperfusion (dyspnoea, orthopnoea, PND, raised JVP, S3, basal crepitations, oedema), supported by elevated natriuretic peptides (BNP/NT-proBNP) and confirmed by transthoracic echocardiography defining LVEF and phenotype - HFrEF <=40%, HFmrEF 41-49%, HFpEF >=50%. Always characterise the underlying aetiology (ischaemic, hypertensive, valvular, cardiomyopathy, arrhythmic).", tx: ["Stabilise acute decompensation - sit upright, oxygen/NIV if hypoxic, IV loop diuretic (furosemide) for congestion, IV nitrate if hypertensive/flash pulmonary oedema; reserve inotropes/vasopressors for hypoperfusion or cardiogenic shock.","Treat the underlying cause and precipitants - revascularise ischaemia, control BP and rate, anticoagulate AF per stroke risk, correct valve disease, arrhythmia, anaemia, thyroid dysfunction and non-adherence.","HFrEF first-line: initiate and up-titrate all four pillars - ARNI (or ACEi/ARB), beta-blocker, MRA and SGLT2 inhibitor - to target/max-tolerated doses.","Adjuncts - loop diuretic for congestion; ivabradine if sinus rate >=70 on maximal beta-blocker (LVEF <=35%); hydralazine-nitrate (especially Black patients or ACEi/ARB-intolerant); IV iron if iron-deficient.","HFpEF/HFmrEF: SGLT2 inhibitor for all, diuretic for congestion, aggressive control of hypertension/AF/comorbidities; MRA and ARNI have benefit at the lower-EF ranges.","Device/advanced care - refer for primary-prevention ICD if LVEF <=35% on >=3 months optimal therapy (NYHA II-III, survival >1 year, regardless of QRS); refer for CRT if LVEF <=35% with LBBB and QRS >=130 ms (Class I >=150 ms) in sinus rhythm; escalate refractory disease to transplant/LVAD assessment; monitor U&E, eGFR, K+, weight and rhythm; in pregnancy avoid ACEi/ARB/ARNI/MRA/SGLT2i/ivabradine."], ix: ["Natriuretic peptides - BNP/NT-proBNP for diagnosis, rule-out and prognosis.","Transthoracic echocardiography - LVEF, chamber size, wall motion, valves and diastolic function.","12-lead ECG (ischaemia, LBBB, AF, LVH) and chest X-ray (cardiomegaly, congestion, effusions).","Bloods - FBC, U&E/eGFR, LFTs, glucose/HbA1c, TFTs, ferritin/transferrin saturation, troponin.","Aetiology work-up - coronary angiography/CT coronary angiography or ischaemia testing; cardiac MRI if infiltrative/inflammatory cardiomyopathy suspected."], dispo: "Confirm with echocardiography and refer to cardiology/heart-failure clinic; admit acute decompensation, cardiogenic shock or refractory disease.", src: "Harrison 22e; ESC 2021/2023 Heart Failure Guidelines" },
    "ischemic_heart_disease": { name: "Ischemic Heart Disease", class: "non_infective", system: "Cardiovascular", dx: "Diagnose from typical exertional angina plus objective evidence of ischaemia – resting/exercise ECG changes, stress imaging (echo/MPI/CMR) or coronary stenosis on CT coronary angiography (first-line anatomical test), with invasive angiography for high-risk or refractory cases. Estimate pre-test probability to guide testing; if acute ischaemic pain, use serial ECG + troponin to exclude/confirm ACS.", tx: ["Exclude/treat ACS first – if acute ischaemic chest pain, give aspirin 300 mg + serial ECG/troponin; activate primary PCI for STEMI, early invasive strategy for high-risk NSTE-ACS.","Aggressive risk-factor control – smoking cessation, Mediterranean diet, physical activity, weight/BP optimisation, glycaemic control in diabetes.","First-line antianginal – beta-blocker or dihydropyridine CCB (combine if needed; avoid non-dihydropyridine CCB + beta-blocker) + short-acting nitrate for symptom relief; escalate with long-acting nitrate, ivabradine, ranolazine or nicorandil if refractory.","Secondary prevention – high-intensity statin (LDL target <1.4 mmol/L and >=50% reduction, add ezetimibe/PCSK9i if unmet), antiplatelet (aspirin 75-100 mg, or clopidogrel if intolerant), and ACE inhibitor/ARB when diabetes, HF, hypertension or CKD coexist.","Revascularisation – refer for coronary angiography and PCI/CABG when symptoms persist despite optimal medical therapy or high-risk anatomy (left main, multivessel with LV dysfunction/diabetes favours CABG).","Refer to cardiology + cardiac rehabilitation; offer annual influenza vaccination; monitor symptoms, lipids, renal function and BP; reassess adherence and ischaemic burden."], ix: ["12-lead ECG at rest and with exercise/stress","Troponin (serial) when acute presentation to exclude ACS","CT coronary angiography or functional stress imaging (stress echo/MPI/CMR)","Transthoracic echocardiography for LV function and structural disease","Bloods – fasting lipids, HbA1c/glucose, FBC, U&E/eGFR, TFTs"], dispo: "Outpatient cardiology + cardiac rehab for stable disease; immediate transfer to PCI-capable centre if ACS suspected.", src: "Harrison 22e · ESC (Chronic Coronary Syndromes 2024)" },
    "mitral_valve_prolapse": { name: "Mitral Valve Prolapse", class: "non_infective", system: "Cardiovascular", dx: "Diagnose on transthoracic echocardiography: systolic displacement of one or both mitral leaflets ≥2 mm above the annular plane in the parasternal long-axis view, ± leaflet thickening (>5 mm = classic/myxomatous). Clinical clue – mid-systolic click ± late-systolic murmur that moves earlier and louder with standing/Valsalva (reduced preload).", tx: ["Asymptomatic MVP with no/trivial regurgitation – reassure, no drugs or activity restriction; periodic clinical and echo surveillance.","Palpitations/atypical chest pain/anxiety – beta-blocker for symptom control; optimise hydration and volume for orthostatic/autonomic symptoms.","Progressive/severe primary mitral regurgitation – definitive treatment is surgery; favour valve repair over replacement at an experienced Heart Valve centre.","Refer for intervention when severe MR is symptomatic, or asymptomatic with LVEF ≤60%, LVESD ≥40 mm, new AF, or pulmonary hypertension (PASP >50 mmHg).","Atrial fibrillation or prior embolism/stroke – rate-control and anticoagulate per AF stroke-prevention pathway.","Endocarditis antibiotic prophylaxis NOT routine – reserve only for prior IE or prosthetic/repaired valve material; counsel on dental/skin hygiene."], ix: ["Transthoracic echocardiography with Doppler – confirm prolapse, quantify MR, LV size/EF, PASP.","ECG – rhythm, atrial fibrillation, repolarisation/QT, ventricular ectopy.","Transoesophageal echo – define leaflet/scallop anatomy and repairability before surgery.","Ambulatory Holter/event monitor – for palpitations or suspected arrhythmia.","Exercise/stress echo – if symptoms discordant with resting MR severity or to assess exertional PASP."], dispo: "Primary care/cardiology outpatient with echo surveillance; refer to a specialist Heart Valve/cardiac surgery centre when severe MR or surgical triggers are met.", src: "Harrison 22e · ESC/EACTS 2021 Valvular Heart Disease" },
    "multiple_and_mixed_valvular_heart": { name: "Multiple and Mixed Valvular Heart Disease", class: "non_infective", system: "Cardiovascular", dx: "Confirm with transthoracic echocardiography plus Doppler – grade each lesion (severity, mechanism, chamber size, LV/RV function, pulmonary pressures) and identify the haemodynamically dominant one. Integrate symptoms, signs and haemodynamics, as combined lesions distort standard severity indices and can mask each other on examination.", tx: ["Grade every lesion, then treat the haemodynamically dominant one – do not manage each valve in isolation, as combined loading conditions shift severity thresholds and physical signs.","Medical therapy is supportive only – diuretics for congestion, rate control, and anticoagulation for AF; when there is significant mitral stenosis or a mechanical prosthesis use a VKA (warfarin), NOT a DOAC. Add guideline heart-failure therapy per LVEF, but use vasodilators/aggressive diuresis cautiously if significant aortic stenosis is present. No drug corrects mechanical valve disease.","Mixed stenosis plus regurgitation of one valve, or several moderate lesions together – intervene when any single component is severe, or when the combined haemodynamic burden produces symptoms or LV dysfunction even if no lesion is individually 'severe'; beware low-flow states under-grading a tight stenosis.","Definitive treatment is valve intervention (repair or replacement) – multivalve disease usually favours combined surgery, but staged/transcatheter options (TAVI, transcatheter mitral/tricuspid repair, balloon valvotomy) suit selected high-risk patients.","Correct significant secondary tricuspid regurgitation or a dilated annulus at the time of left-sided surgery – do not leave it untreated.","Refer early to a multidisciplinary Heart Valve Team for lesion integration, timing and intervention choice; anticoagulate mechanical prostheses lifelong with a VKA (warfarin) and give endocarditis prophylaxis where indicated."], ix: ["Transthoracic echocardiography with Doppler – grade each lesion, chamber size, LV/RV function, pulmonary artery pressure","Transoesophageal echo – mechanism/repairability, prosthesis assessment, exclude LA thrombus before valvotomy","ECG (AF, chamber hypertrophy) and chest radiograph (chamber enlargement, pulmonary congestion)","Coronary angiography or CT coronary angiography pre-surgery; cardiac CT for annular sizing/TAVI planning","Exercise testing and BNP/NT-proBNP where symptom status or lesion severity is discordant"], dispo: "Refer to cardiology / multidisciplinary Heart Valve Team; surgical or transcatheter intervention at a valve centre.", src: "Harrison 22e · ESC/EACTS 2021 valvular heart disease (AHA/ACC 2020 concordant)" },
    "paroxysmal_supraventricular_tachycardias": { name: "Paroxysmal Supraventricular Tachycardias", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG during tachycardia shows a regular narrow-complex tachycardia (rate ~150–250/min); the P-wave relationship distinguishes AVNRT (pseudo-r'/pseudo-S, RP<70ms) from AVRT (retrograde P after QRS) and atrial tachycardia. Confirm mechanism by response to vagal manoeuvres or adenosine, and capture a sinus-rhythm ECG to detect pre-excitation (delta wave, WPW).", tx: ["Unstable (hypotension, ischaemia, pulmonary oedema, altered mentation) – immediate synchronised DC cardioversion.","Stable – vagal manoeuvres first: modified Valsalva (legs-raised) or carotid sinus massage (avoid if carotid bruit or recent stroke/TIA).","If vagal fails – IV adenosine rapid push with flush (6mg then 12mg); also unmasks atrial flutter/AT.","Second-line acute termination – IV verapamil/diltiazem (avoid in HFrEF/hypotension) or IV beta-blocker; avoid AV-nodal blockers if pre-excited (WPW-AF) – use procainamide/ibutilide or DC cardioversion.","Definitive – catheter ablation (first-line curative for recurrent AVNRT/AVRT); alternative chronic prophylaxis with beta-blocker or non-dihydropyridine CCB, or flecainide/propafenone if structurally normal heart.","Pregnancy – vagal then adenosine first-line, beta-1 selective blocker (e.g. metoprolol) for prophylaxis, defer ablation where possible; overt WPW with syncope/pre-excited AF – early electrophysiology referral."], ix: ["12-lead ECG during tachycardia and in sinus rhythm (assess pre-excitation)","Ambulatory/Holter or event monitor if paroxysms undocumented","Serum electrolytes, magnesium and TSH","Transthoracic echocardiogram to exclude structural heart disease","Electrophysiology study (diagnostic and therapeutic at ablation)"], dispo: "Acute episode via ED/monitored bed; recurrent or pre-excited PSVT – refer to cardiology/electrophysiology for ablation.", src: "Harrison 22e · 2019 ESC SVT" },
    "polymorphic_ventricular_tachycardia_and_ve": { name: "Polymorphic Ventricular Tachycardia and Ventricular Fibrillation", class: "non_infective", system: "Cardiovascular", dx: "Confirm on 12-lead ECG/continuous telemetry: polymorphic VT shows continuously varying QRS morphology/axis; torsades de pointes is polymorphic VT twisting around baseline on a prolonged QT; VF shows chaotic irregular deflections with no organised QRS. Correlate with pulse/haemodynamics – pulseless polymorphic VT/VF is a cardiac-arrest rhythm.", tx: ["Pulseless VT/VF – immediate ACLS: high-quality CPR + unsynchronised defibrillation, repeat every 2 min; adrenaline 1 mg IV every 3–5 min. (Unstable polymorphic VT even with a pulse is also treated with unsynchronised shock.)","Refractory VF/pulseless VT – amiodarone 300 mg IV (or lidocaine) after 3rd shock; consider dual-sequence/left-lateral pad defibrillation; treat reversible causes (ischaemia, hypoxia, electrolytes).","Correct triggers – replete K⁺ and Mg²⁺ (target K⁺ ~4.5–5.0), IV magnesium sulfate for torsades, stop QT-prolonging drugs; urgent revascularisation if ischaemic polymorphic VT.","Torsades/pause-dependent (acquired) long-QT – IV magnesium first-line; raise heart rate to shorten QT with isoprenaline infusion or temporary transvenous/atrial overdrive pacing (isoprenaline contraindicated in congenital LQTS and ischaemia).","Electrical storm – IV beta-blockade (esmolol/propranolol) ± amiodarone, deep sedation; escalate to mechanical support (IABP/VA-ECMO), stellate-ganglion block, catheter ablation of triggering PVCs.","Secondary prevention once stable – treat underlying disease and refer for ICD in VF/unstable-VT survivors not due to a fully reversible cause; beta-blocker ± flecainide (flecainide only for CPVT/channelopathy, not structural/ischaemic substrate) and genetic testing for CPVT/inherited channelopathy."], ix: ["12-lead ECG (QTc, ischaemia, Brugada/QT pattern) plus continuous telemetry","Electrolytes – K⁺, Mg²⁺, Ca²⁺ – with renal and thyroid function","Serial troponin and 12-lead for acute ischaemia; urgent coronary angiography if indicated","Echocardiography for structural disease/LV function; cardiac MRI where cause unclear","Medication/toxicology review and genetic testing for suspected LQTS/CPVT/Brugada"], dispo: "Resuscitate in situ then admit to CCU/ICU under cardiology/electrophysiology; refer for ICD and inherited-arrhythmia/genetic evaluation.", src: "Harrison 22e · ESC 2022 Ventricular Arrhythmias & Sudden Cardiac Death · AHA ACLS" },
    "premature_ventricular_contractions_nonsust": { name: "Premature Ventricular Contractions, Nonsustained Idioventricular Rhythm", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG: PVCs are wide (>120 ms) premature beats with a full compensatory pause; accelerated idioventricular rhythm (AIVR) is a regular wide-complex rhythm at 40–120/min near the sinus rate, with gradual onset/offset and frequent fusion/capture beats. Quantify burden and morphology on 24–48 h Holter/ambulatory monitoring.", tx: ["AIVR (typically reperfusion/post-MI) – benign and self-limiting; no antiarrhythmic. Treat only if haemodynamic compromise from lost AV synchrony (atropine to raise sinus rate) – do not suppress an escape rhythm.","Asymptomatic low-burden PVCs, structurally normal heart – reassurance; withdraw triggers (caffeine, alcohol, stimulants) and correct hypokalaemia/hypomagnesaemia.","Symptomatic PVCs – first-line beta-blocker; alternative non-dihydropyridine calcium-channel blocker (verapamil/diltiazem), avoiding non-DHP CCBs if LV dysfunction.","Refractory/high-burden – flecainide or propafenone if no structural disease, sotalol or amiodarone if structural disease; catheter ablation is first-line for idiopathic outflow-tract PVCs and preferred when drugs fail.","High PVC burden (>10–15%) – screen and monitor with echocardiography for PVC-induced cardiomyopathy; suppression/ablation can reverse LV dysfunction.","Structural/ischaemic substrate – treat the underlying disease, assess SCD risk and ICD indication; refer to cardiology/electrophysiology."], ix: ["12-lead ECG – morphology, coupling interval, capture/fusion beats","24–48 h Holter/ambulatory ECG to quantify PVC burden and morphology","Transthoracic echocardiography – LV function and structural disease","Serum electrolytes (K, Mg) and thyroid function","Exercise/stress test ± cardiac MRI or coronary assessment if ischaemia/structural disease suspected"], dispo: "Primary care/outpatient reassurance if benign; refer to cardiology/electrophysiology for high burden (>10%), beta-blocker-refractory symptoms, LV dysfunction, or structural/ischaemic heart disease.", src: "Harrison 22e · ESC 2022 (ventricular arrhythmias & prevention of SCD)" },
    "pulmonic_valve_disease": { name: "Pulmonic Valve Disease", class: "non_infective", system: "Cardiovascular", dx: "Confirm with transthoracic echocardiography plus Doppler – grades pulmonary stenosis by peak gradient (mild <36 mmHg, moderate 36–64, severe >64 mmHg / peak velocity >4 m/s) and quantifies pulmonary regurgitation, valve morphology and RV size/function. Clinical clues – PS: ejection systolic murmur with a systolic ejection click (decreases with inspiration) at the left upper sternal edge, widely split S2 with soft/delayed P2; PR: decrescendo diastolic murmur (Graham Steell murmur if pulmonary hypertension).", tx: ["Mild PS (peak gradient <36 mmHg) – no intervention; reassure and give periodic echo surveillance, prognosis excellent and progression rare.","Severe PS (peak Doppler gradient >64 mmHg / velocity >4 m/s) – percutaneous balloon pulmonary valvuloplasty is the treatment of choice for a mobile, non-dysplastic (domed) valve; it is indicated in symptomatic patients AND in asymptomatic patients with severe PS (peak gradient >64 mmHg) or with RV dysfunction (ESC 2020 / AHA-ACC 2018 Class I).","Surgical valvotomy/valve replacement where valvuloplasty is unsuitable – dysplastic valve (e.g. Noonan syndrome), hypoplastic annulus, sub/supravalvular stenosis, or associated significant PR.","Pulmonary regurgitation – treat the underlying cause (e.g. pulmonary hypertension); most PR is well tolerated and needs no specific valve therapy.","Severe symptomatic PR (typically post-tetralogy-of-Fallot repair) with progressive RV dilatation/dysfunction or arrhythmia – refer for pulmonary valve replacement (surgical or transcatheter).","Monitor with serial echo and cardiac MRI for indexed RV volumes; give endocarditis prophylaxis only for prosthetic valve/prosthetic repair material, prior IE, or unrepaired cyanotic CHD; maintain lifelong ACHD-centre follow-up."], ix: ["Transthoracic echocardiography with Doppler – primary diagnostic and severity tool","ECG – right axis deviation and RV hypertrophy in significant PS","Chest X-ray – post-stenotic pulmonary artery dilatation and RV enlargement","Cardiac MRI – indexed RV volumes and PR regurgitant fraction, especially post-TOF repair","Cardiac catheterisation – direct (peak-to-peak) gradient measurement when echo is inconclusive or pre-intervention"], dispo: "Outpatient cardiology; refer severe PS/PR to a structural/adult-congenital-heart-disease (ACHD) centre for intervention.", src: "Harrison 22e · ESC 2020 ACHD · AHA/ACC 2018 ACHD" },
    "st_segment_elevation_myocardial_infarction": { name: "ST-Segment Elevation Myocardial Infarction", class: "non_infective", system: "Cardiovascular", dx: "Ischaemic symptoms (chest pain/equivalent ≥20 min) plus 12-lead ECG showing persistent ST-elevation ≥1 mm in ≥2 contiguous limb leads or ≥2 mm (men)/≥1.5 mm (women) in ≥2 contiguous precordial leads (V2–V3), or new/presumed-new LBBB with ongoing ischaemia. Reperfuse on the ECG – do not await troponin, though a rise/fall in high-sensitivity troponin confirms infarction.", tx: ["Immediate – loading aspirin 300 mg chewed; O2 only if SpO2 <90%; sublingual/IV GTN and IV opioid (e.g. morphine) for ongoing pain – AVOID nitrates in hypotension, inferior/right-ventricular infarction, or recent PDE5-inhibitor use; cardiac monitor with defibrillator to hand.","Activate reperfusion pathway at once – primary PCI is first-line if deliverable within 120 min of STEMI diagnosis.","If PCI not achievable ≤120 min – give fibrinolysis (tenecteplase, weight-adjusted) within 10 min, then transfer for early/rescue angiography (pharmacoinvasive strategy).","Antithrombotics – dual antiplatelet: aspirin plus a P2Y12 inhibitor (prasugrel or ticagrelor preferred with primary PCI; clopidogrel if these contraindicated or when fibrinolysis is used) plus a parenteral anticoagulant (UFH or enoxaparin periprocedurally; enoxaparin preferred with lysis).","Secondary prevention before discharge – high-intensity statin, oral beta-blocker, ACE inhibitor/ARB, and a mineralocorticoid-receptor antagonist if LVEF ≤40% with HF or diabetes; continue DAPT 12 months (duration individualised to bleeding/ischaemic risk).","Monitor continuous ECG for arrhythmia; identify and treat complications (cardiogenic shock, mechanical rupture, LV thrombus); early cardiac rehabilitation and risk-factor modification."], ix: ["Serial 12-lead ECG – immediate and repeated","High-sensitivity cardiac troponin – serial (do not delay reperfusion for results)","Urgent coronary angiography – diagnostic and therapeutic","Transthoracic echocardiography – LVEF, wall-motion, mechanical complications","FBC, U&E/creatinine, glucose/HbA1c, lipid profile"], dispo: "Emergency admission to a PCI-capable centre via primary-PCI pathway; coronary care unit/ICU under cardiology.", src: "Harrison 22e · ESC 2023 ACS guideline" },
    "sustained_ventricular_tachycardia": { name: "Sustained Ventricular Tachycardia", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG during tachycardia shows regular wide-complex (QRS >120 ms) rate >100/min; VT favoured over SVT-with-aberrancy by AV dissociation, capture/fusion beats, extreme axis or precordial concordance. Sustained = >30 s or requiring termination for haemodynamic compromise; assume VT in any wide-complex tachycardia with structural heart disease. Avoid empiric AV-nodal blockers (verapamil/diltiazem) in undifferentiated wide-complex tachycardia — may precipitate collapse if the rhythm is VT.", tx: ["Assess haemodynamic stability – pulseless VT → unsynchronised defibrillation with CPR/ACLS; unstable with a pulse (hypotension, ischaemia, pulmonary oedema, altered mentation) → immediate synchronised DC cardioversion (defibrillate if polymorphic or cannot synchronise).","Stable monomorphic VT – IV antiarrhythmic: procainamide preferred first-line when LV function preserved/only mildly reduced (ESC 2022, PROCAMIO); amiodarone if severe LV dysfunction/heart failure; lidocaine an option in acute ischaemia; synchronised cardioversion if drugs fail or patient deteriorates.","Polymorphic VT/torsades – IV magnesium sulphate, correct K+/Mg2+, withdraw QT-prolonging drugs; isoprenaline or overdrive pacing for pause-/bradycardia-dependent (long-QT) forms; urgent revascularisation plus beta-blockade if ischaemic; defibrillate if unstable.","Identify and treat reversible triggers – acute ischaemia/MI, electrolyte disturbance, drug toxicity, decompensated heart failure; for VT storm use beta-blockade, amiodarone, sedation and consider urgent ablation.","Definitive therapy – ICD for secondary prevention with structural heart disease/reduced EF; catheter ablation for recurrent drug-refractory monomorphic VT or storm; optimise underlying cardiomyopathy/heart-failure therapy.","Urgent cardiology/electrophysiology referral for all sustained VT; ICD evaluation before discharge."], ix: ["12-lead ECG during and after episode, plus baseline/prior ECGs and continuous telemetry","Serum electrolytes (K+, Mg2+, Ca2+) and renal/hepatic function","Cardiac troponin and ischaemia workup ± coronary angiography","Transthoracic echocardiography for LV function and structural disease; cardiac MRI for scar/infiltration","Electrophysiology study for risk stratification/ablation planning in selected cases"], dispo: "Admit to CCU/monitored bed with continuous telemetry; urgent cardiology/electrophysiology referral and ICD assessment.", src: "Harrison 22e · ESC 2022 (ventricular arrhythmias / prevention of SCD) · AHA ACLS 2020" },
    "the_bradyarrhythmias_disorders_of_the": { name: "The Bradyarrhythmias: Disorders of the Atrioventricular Node", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG localises and grades the block — PR prolongation (first-degree), progressive PR lengthening with a dropped beat (Mobitz I), fixed PR with sudden non-conducted P waves or 2:1 (Mobitz II), or AV dissociation with a slow escape (third-degree/complete). Ambulatory or inpatient telemetry captures intermittent/paroxysmal block and correlates symptoms with rhythm.", tx: ["Assess haemodynamic stability — if unstable (hypotension, shock, ischaemia, heart failure, syncope): IV atropine 0.5 mg boluses every 3-5 min (max 3 mg). Atropine is often ineffective, and may paradoxically worsen, infranodal block (Mobitz II or complete block with a wide-QRS escape), so do NOT delay transcutaneous pacing and/or a chronotropic infusion (isoprenaline/adrenaline/dopamine) as a bridge.","Identify and reverse causes — stop AV-nodal blocking drugs (beta-blockers, non-dihydropyridine calcium-channel blockers [verapamil/diltiazem], digoxin, amiodarone); correct hyperkalaemia, hypothyroidism and ischaemia (esp. inferior MI); treat Lyme/infiltrative or infective disease.","Insert temporary transvenous pacing for persistent high-grade or complete block causing instability whilst awaiting recovery or a permanent device.","Permanent pacemaker — definitive for symptomatic or high-grade acquired AV block (third-degree, advanced/Mobitz II second-degree) not due to a reversible cause; dual-chamber pacing preferred to preserve AV synchrony.","Consider conduction-system pacing (His/left-bundle-branch-area) or CRT where a high ventricular-pacing burden is anticipated with LV dysfunction.","First-degree and Mobitz I block — no pacing unless symptomatic; monitor and address reversible contributors."], ix: ["12-lead ECG — localise and grade block; assess escape rhythm width and rate","Ambulatory/telemetry monitoring (Holter, event/loop recorder) for intermittent block and symptom correlation","Electrolytes (K+, Ca, Mg), renal function, TFTs; troponin if ischaemia suspected","Echocardiography — structural heart disease and LV function","Targeted aetiology tests where indicated (Lyme serology, medication review, EPS if unexplained syncope)"], dispo: "Admit high-grade/symptomatic block to a monitored bed (telemetry +/- temporary pacing); urgent cardiology/electrophysiology referral for permanent device assessment.", src: "Harrison 22e · ESC 2021 Cardiac Pacing and CRT · ACC/AHA/HRS 2018 Bradycardia guideline" },
    "tricuspid_valve_disease": { name: "Tricuspid Valve Disease", class: "non_infective", system: "Cardiovascular", dx: "Confirm with transthoracic echocardiography – grade severity, define mechanism (primary/structural vs secondary/functional) and assess RV size/function and estimated PA systolic pressure. Add transoesophageal echo for pre-intervention anatomy; right heart catheterisation resolves discordant non-invasive data.", tx: ["Treat congestion/right heart failure – loop diuretic ± aldosterone antagonist, sodium/fluid restriction.","Address the driver of secondary (functional) TR – optimise left-sided valve/myocardial disease, control AF and treat pulmonary hypertension.","Surgery for severe TR – annuloplasty (repair preferred over replacement) at the time of left-sided valve surgery (Class I); consider for symptomatic isolated primary severe TR or progressive RV dilatation/dysfunction.","Transcatheter intervention – T-TEER (TriClip) or TTVR (EVOQUE) for symptomatic severe TR despite optimal medical therapy in high surgical-risk patients, after multidisciplinary heart-team review at a valve centre.","Tricuspid stenosis – diuretics for congestion; bioprosthetic replacement or repair for severe symptomatic disease, usually alongside mitral surgery; anticoagulate tricuspid bioprostheses given higher thrombosis risk.","Right-sided infective endocarditis (IVDU) – prolonged targeted antibiotics; valve repair/vegetectomy if medical therapy fails, vegetations large, or right heart failure."], ix: ["Transthoracic echocardiography – severity, mechanism, RV function, PASP","Transoesophageal echocardiography – mechanism and pre-procedural planning","ECG – atrial fibrillation, RV strain/hypertrophy; CXR – RA/cardiac enlargement","Right heart catheterisation – haemodynamics and PA pressure when non-invasive data discordant or pre-intervention","Cardiac MRI for RV volumes/function ± NT-proBNP"], dispo: "Cardiology referral; multidisciplinary heart-team assessment at a tertiary valve centre for surgical or transcatheter candidates.", src: "Harrison 22e · AHA/ACC 2020 (VHD)" },
    "arterial_diseases_of_the_extremities": { name: "Arterial Diseases of the Extremities", class: "non_infective", system: "Cardiovascular (peripheral vascular)", dx: "Peripheral artery disease (PAD) confirmed by resting ankle–brachial index (ABI) ≤0.90; borderline 0.91–0.99 or non-compressible calcified vessels (ABI >1.40, e.g. diabetes/CKD) warrant toe–brachial index (<0.70) or exercise ABI (post-exercise fall ≥20%). Duplex ultrasound, CT/MR angiography or catheter angiography localises and grades stenosis before planned revascularisation.", tx: ["Acute limb ischaemia or critical limb-threatening ischaemia (rest pain, ulcers, gangrene) – urgent vascular surgery referral; give IV unfractionated heparin immediately with analgesia and arrange emergency revascularisation (catheter thrombolysis for viable/marginally threatened limbs, thromboembolectomy or bypass for immediately threatened limbs).","Aggressive risk-factor control – supervised exercise therapy (30–45 min ≥3×/week), complete smoking cessation, high-intensity statin ± ezetimibe/PCSK9 inhibitor, BP optimisation (ACEi/ARB reasonable) and glycaemic control.","Antithrombotic therapy – single antiplatelet (clopidogrel preferred, or aspirin); add low-dose rivaroxaban 2.5 mg BD to aspirin in high-risk symptomatic or post-revascularisation PAD to cut MACE/MALE (individualise for bleeding risk; avoid if CrCl <15 mL/min).","Claudication symptom relief – cilostazol first-line (contraindicated in any-grade heart failure); exercise remains the cornerstone.","Revascularisation for lifestyle-limiting claudication refractory to medical therapy or for CLTI – endovascular angioplasty/stenting or surgical bypass per anatomy/lesion pattern.","Structured foot/wound care, treat infection, offer influenza vaccination; refer non-healing ulcers or tissue loss to a multidisciplinary limb-salvage team."], ix: ["Resting ABI (add exercise ABI or toe–brachial index if vessels non-compressible)","Arterial duplex ultrasound to localise stenosis/occlusion","CT or MR angiography (or catheter angiography) for revascularisation planning","Fasting lipids, HbA1c/glucose, renal function","Foot inspection ± wound/tissue assessment in suspected CLTI"], dispo: "Outpatient vascular medicine/surgery clinic; urgent/emergency vascular surgery for acute or critical limb ischaemia.", src: "Harrison 22e · ESC/ESVS 2024 peripheral arterial and aortic diseases" },
    "deep_venous_thrombosis_and_pulmonary": { name: "Deep-Venous Thrombosis and Pulmonary Thromboembolism", class: "non_infective", system: "Cardiovascular / Venous (Vascular)", dx: "Confirm DVT with compression ultrasonography (non-compressible vein); confirm PE with CT pulmonary angiography. Risk-stratify first with validated pre-test probability (Wells/Geneva) plus D-dimer — normal D-dimer with low pre-test probability excludes VTE without imaging.", tx: ["Risk-stratify PE severity — high-risk (haemodynamic instability/shock) vs intermediate vs low (sPESI); for DVT assess extent and bleeding risk.","High-risk/massive PE — resuscitate, give supplemental O2 and IV access, and give systemic thrombolysis (alteplase) unless contraindicated; consider catheter-directed therapy or surgical/catheter embolectomy if thrombolysis fails or is contraindicated.","Anticoagulate promptly (empirically if high suspicion and low bleeding risk) — first-line DOAC (apixaban or rivaroxaban) for most DVT and haemodynamically stable PE.","Alternatives — LMWH bridging to a VKA (target INR 2–3) or LMWH monotherapy; use UFH if thrombolysis anticipated, severe renal impairment, or haemodynamic instability.","Continue ≥3 months; extend indefinitely for unprovoked/recurrent VTE or persisting risk factors — reassess bleeding risk periodically; reserve IVC filter for absolute contraindication to anticoagulation.","Special populations — pregnancy: LMWH (avoid DOACs and warfarin); active cancer: DOAC or LMWH; CrCl <30: UFH (preferred) or dose-adjusted LMWH with anti-Xa monitoring, or warfarin."], ix: ["Compression ultrasound of proximal leg veins (DVT)","CT pulmonary angiography (PE); V/Q scan if CTPA contraindicated","D-dimer (with pre-test probability score — Wells/Geneva)","ECG and troponin/BNP for RV strain risk-stratification in PE","Echocardiography to assess RV dysfunction in suspected high/intermediate-risk PE"], dispo: "Admit high/intermediate-risk PE (consider ICU/monitored bed); low-risk PE (sPESI 0) and uncomplicated DVT — outpatient anticoagulation with early review.", src: "Harrison 22e · ESC 2019 (Acute Pulmonary Embolism)" },
    "ards": { name: "Acute Respiratory Distress Syndrome (ARDS)", class: "non_infective", system: "Critical Care", dx: "Clinical diagnosis by Berlin/2023 Global definition – acute hypoxaemic respiratory failure within 1 week of a known insult, bilateral opacities on CXR/CT not fully explained by effusion/collapse/nodules, and respiratory failure not fully attributable to cardiac failure or fluid overload. Grade severity by PaO2/FiO2 on PEEP ≥5 cmH2O – mild 200–300, moderate 100–200, severe <100; exclude cardiogenic oedema with echocardiography.", tx: ["Treat the precipitant – source control, early broad-spectrum antibiotics for sepsis, manage aspiration/pancreatitis/trauma.","Lung-protective ventilation – tidal volume 6 mL/kg predicted body weight, plateau pressure <30 cmH2O, driving pressure <15 cmH2O; accept permissive hypercapnia (pH >7.20).","Titrate PEEP to oxygenation/compliance (higher-PEEP strategy in moderate–severe); target SpO2 88–95%; adopt conservative fluid strategy once perfusion adequate.","Prone position ≥12–16 h/day for moderate–severe ARDS (P/F <150); add short-course neuromuscular blockade (cisatracurium) for early severe ARDS with ventilator dyssynchrony.","Consider dexamethasone in moderate–severe or COVID-19 ARDS; refer refractory hypoxaemia (P/F <80 despite optimisation) for venovenous ECMO; inhaled pulmonary vasodilators only as rescue bridge.","Supportive care – lung-protective sedation, VTE and stress-ulcer prophylaxis, enteral nutrition, daily awakening/spontaneous-breathing trials once improving."], ix: ["Arterial blood gas with PaO2/FiO2 ratio","Chest radiograph and/or chest CT","Echocardiography – exclude cardiogenic pulmonary oedema, assess RV","Sepsis screen – blood/sputum cultures, FBC, CRP/procalcitonin, lactate","BNP/NT-proBNP to help exclude cardiac failure"], dispo: "Intensive care – invasive ventilation with lung-protective strategy; refer to regional ECMO centre if refractory hypoxaemia.", src: "Harrison 22e · ATS/ESICM/SCCM" },
    "DRESS_SYNDROME": { name: "DRESS syndrome", class: "non_infective", system: "Dermatology", dx: "Clinical diagnosis supported by RegiSCAR criteria - morbilliform eruption with facial oedema, fever, lymphadenopathy, eosinophilia/atypical lymphocytosis and internal-organ involvement (esp. hepatitis) arising 2-8 weeks after a culprit drug (aromatic anticonvulsants, allopurinol, sulfonamides, vancomycin, minocycline, dapsone). Skin biopsy and exclusion of infective/other causes are supportive. Note: unlike SJS/TEN, DRESS does NOT cause epidermal detachment.", tx: ["Stop the culprit drug immediately and avoid all cross-reacting agents - the single most important intervention.","Admit for supportive care - IV fluids, electrolyte correction, temperature control, skin emollients; nurse in dermatology, escalating to ICU/HDU if erythroderma with skin-barrier failure or multi-organ failure (DRESS does not cause TEN-like skin detachment).","First-line for organ involvement: systemic corticosteroids - oral/IV prednisolone 0.5-1 mg/kg/day (consider IV methylprednisolone pulses for fulminant hepatitis or myocarditis), then slow taper over >=8-12 weeks (up to 3-6 months) to prevent relapse.","Skin-limited/mild disease without significant organ involvement: potent topical corticosteroids and antihistamines; avoid introducing unnecessary new drugs (empirical antibiotics/antipyretics) that may confound or re-sensitise.","Steroid-refractory or life-threatening disease (fulminant hepatitis, myocarditis): specialist-directed escalation to ciclosporin, mycophenolate mofetil, or IVIG (IVIG generally combined with corticosteroids, not as monotherapy).","Monitor LFTs, renal and cardiac function through the acute illness with a baseline ECG in all patients (myocarditis is a leading, often silent, cause of death); screen for late autoimmune sequelae (thyroiditis, type 1 diabetes) for months, document the drug allergy and counsel on lifelong avoidance."], ix: ["FBC with differential - eosinophilia (>0.7 x10^9/L) and atypical lymphocytes","LFTs and renal function with urinalysis - detect hepatic/renal involvement","Skin biopsy - supportive histology, excludes mimics","HHV-6 (+/- CMV/EBV) serology/PCR - viral reactivation","Baseline ECG and troponin in all patients; echocardiography if cardiac symptoms or abnormal markers; baseline TFTs and glucose for later autoimmune sequelae"], dispo: "Admit - inpatient under dermatology with physician co-management; ICU/HDU if severe multi-organ involvement or erythroderma with skin-barrier failure (not epidermal detachment, which would indicate SJS/TEN or overlap).", src: "Harrison 22e - BAD" },
    "ERYTHEMA_NODOSUM": { name: "Erythema nodosum", class: "non_infective", system: "Dermatology", dx: "Clinical diagnosis — crops of tender, poorly-demarcated, erythematous-to-violaceous nodules, typically bilateral over the pretibial shins, that do not ulcerate and heal without scarring (bruise-like colour evolution). Reserve deep incisional biopsy (must include subcutaneous fat) for atypical or persistent lesions — shows septal panniculitis without vasculitis.", tx: ["Identify and treat/remove the trigger — antibiotics for streptococcal infection, withdraw offending drug (sulfonamides, oral contraceptive), treat underlying sarcoidosis/TB/IBD/infection.","Supportive first-line — bed rest, leg elevation, compression, and NSAIDs for pain/inflammation; avoid NSAIDs in IBD-associated EN (may flare bowel disease) and use with caution in renal impairment/elderly/pregnancy.","Persistent/recurrent disease — oral potassium iodide (SSKI) for several weeks; monitor thyroid function and avoid in pregnancy or overt thyroid disease.","Severe/refractory disease — short course systemic corticosteroids ONLY after infection (especially TB) and malignancy excluded; colchicine or dapsone as steroid-sparing alternatives (screen for G6PD deficiency before dapsone due to haemolysis risk; colchicine preferred in Behcet-associated EN).","Monitoring — most cases self-limiting, resolving over 3-6 weeks; escalate work-up for underlying cause if lesions persist beyond 6-8 weeks or recur.","Pregnancy — supportive care only (avoid NSAIDs and potassium iodide); EN may be pregnancy/OCP-related and settles post-partum."], ix: ["Throat swab + ASO/anti-DNase B titre (streptococcal trigger)","Chest radiograph — bilateral hilar lymphadenopathy (sarcoidosis/Lofgren syndrome) or TB","FBC, ESR/CRP","Tuberculin skin test or IGRA","Targeted tests per clinical clues — faecal calprotectin/colonoscopy (IBD), fungal serology, pregnancy test"], dispo: "Outpatient management; refer to dermatology if diagnosis uncertain or refractory, and to the relevant specialty (respiratory/gastroenterology/ID) per identified underlying cause.", src: "Harrison 22e · BAD" }
  };
})();
